import React, { useState, useRef, useEffect } from 'react';

type Track = { id: string; name: string; path?: string; src?: string; file?: File; cover?: string; backingActive?: boolean; _originalSrc?: string };
type Playlist = { name: string; tracks: Track[] };

export default function App() {
  const [tracks, setTracks] = useState<Track[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [current, setCurrent] = useState<number | null>(null);
  const [selected, setSelected] = useState<number | null>(null);
  const [selectedPlaylistName, setSelectedPlaylistName] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const seekingRef = useRef<boolean>(false);
  const addFilesInputRef = useRef<HTMLInputElement | null>(null);
  const addFolderInputRef = useRef<HTMLInputElement | null>(null);
  const [logs, setLogs] = useState<string[]>([]);
  const playLockRef = useRef<boolean>(false);
  const [view, setView] = useState<'player'|'config'>('player');
  const [seekTime, setSeekTime] = useState<number>(0);
  const [duration, setDuration] = useState<number>(0);

  // sync audio progress and metadata (also reflect play/pause state)
  useEffect(() => {
    const a = audioRef.current;
    if (!a) return;
    const onTime = () => { if (!seekingRef.current) setSeekTime(a.currentTime || 0); };
    const onMeta = () => setDuration(a.duration || 0);
    const onPlay = () => setIsPlaying(true);
    const onPause = () => setIsPlaying(false);
    a.addEventListener('timeupdate', onTime);
    a.addEventListener('loadedmetadata', onMeta);
    a.addEventListener('durationchange', onMeta);
    a.addEventListener('play', onPlay);
    a.addEventListener('pause', onPause);
    return () => {
      try { a.removeEventListener('timeupdate', onTime); } catch(e){}
      try { a.removeEventListener('loadedmetadata', onMeta); } catch(e){}
      try { a.removeEventListener('durationchange', onMeta); } catch(e){}
      try { a.removeEventListener('play', onPlay); } catch(e){}
      try { a.removeEventListener('pause', onPause); } catch(e){}
    };
  }, [audioRef]);

  // playback + audio routing states
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState<number>(0.5);
  const [pan, setPan] = useState<number>(0);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<any>(null);
  const gainRef = useRef<any>(null);
  const pannerRef = useRef<any>(null);
  const workletRef = useRef<any>(null);
  const shifterRef = useRef<any>(null);
  const shifterPollRef = useRef<number | null>(null);
  const prevVolumeRef = useRef<number>(0.5);
  const [transpose, setTranspose] = useState<number>(0); // semitones (-12..12)

  // backing track preferences/state
  const [autoGenerateBacking, setAutoGenerateBacking] = useState<boolean>(false);
  const [backingAvailableMap, setBackingAvailableMap] = useState<Record<string, boolean>>({});
  // guards for async readFile requests to avoid stale callbacks applying blobs
  const readRequestIdRef = useRef<Record<string, number>>({});
    // track id currently requested for playback (synchronous guard across async callbacks)
    const currentTrackIdRef = useRef<string | null>(null);


  // create audio graph when audio element is available
  useEffect(() => {
    const a = audioRef.current;
    if (!a) return;
    if (audioCtxRef.current) return; // already created
    try {
      const C = (window as any).AudioContext || (window as any).webkitAudioContext;
      if (!C) return;
        const ctx = new C();
      audioCtxRef.current = ctx;
      const src = ctx.createMediaElementSource(a);
      const gain = ctx.createGain();
      let panner: any = null;
      try { panner = ctx.createStereoPanner ? ctx.createStereoPanner() : null; } catch(e) { panner = null; }
      sourceRef.current = src;
      gainRef.current = gain;
      pannerRef.current = panner;

      // attempt to load the pitch-shifter AudioWorklet processor (skeleton)
      try {
        // Vite serves files under the module graph; use import.meta.url to resolve relative path
        const moduleURL = new URL('./pitch-shifter-processor.js', import.meta.url);
        // Load worklet module asynchronously in an IIFE to avoid making the effect callback async
        (async () => {
          try {
            await ctx.audioWorklet.addModule(moduleURL.href);
            const workletNode = new AudioWorkletNode(ctx, 'pitch-shifter-processor', { numberOfInputs: 1, numberOfOutputs: 1, outputChannelCount: [2] });
            workletRef.current = workletNode;
            // connect graph: media element -> worklet -> panner? -> gain -> destination
            if (panner) {
              src.connect(workletNode);
              workletNode.connect(panner);
              panner.connect(gain);
            } else {
              src.connect(workletNode);
              workletNode.connect(gain);
            }
          } catch (e) {
            console.warn('AudioWorklet module load failed, falling back to direct connect', e);
            if (panner) { src.connect(panner); panner.connect(gain); } else { src.connect(gain); }
          }
        })();
      } catch (e) {
        // fallback: connect directly when worklet not available
        console.warn('AudioWorklet not available or failed to load, falling back to direct connect', e);
        if (panner) { src.connect(panner); panner.connect(gain); } else { src.connect(gain); }
      }

      gain.connect(ctx.destination);
      gain.gain.value = volume;
      if (panner && typeof panner.pan !== 'undefined') panner.pan.value = pan;
    } catch (e) { console.warn('audio graph setup failed', e); }
  }, [audioRef]);

  // reflect volume and pan changes into graph and element
  useEffect(() => {
    if (audioRef.current) try{ audioRef.current.volume = volume; } catch(e){}
    if (gainRef.current) try{ gainRef.current.gain.value = volume; } catch(e){}
  }, [volume]);
  useEffect(() => {
    if (pannerRef.current && typeof pannerRef.current.pan !== 'undefined') try{ pannerRef.current.pan.value = pan; } catch(e){}
  }, [pan]);

  // reflect transpose changes into worklet (skeleton)
  useEffect(() => {
    try {
      if (workletRef.current && workletRef.current.port) {
        workletRef.current.port.postMessage({ type: 'setSemitones', value: transpose });
      }
      // If using the SoundTouch PitchShifter, update its semitones as well
      if (shifterRef.current) {
        try { shifterRef.current.pitchSemitones = transpose; } catch(e) { /* ignore */ }
      }
      // Note: the current processor is a pass-through skeleton. Replace processor with a
      // real pitch-shifting implementation (SoundTouch or similar) to get audible transpose
      // without affecting tempo when using the worklet implementation.
    } catch (e) { console.warn('transpose update failed', e); }
  }, [transpose]);

  function formatTime(t: number) {
    if (!t || isNaN(t)) return '0:00';
    const m = Math.floor(t / 60);
    const s = Math.floor(t % 60);
    return `${m}:${String(s).padStart(2,'0')}`;
  }

  function seekAndPlay(time: number) {
    try {
      if (shifterRef.current) {
        try {
          const dur = shifterRef.current.duration || duration || 0;
          const perc = dur ? Math.max(0, Math.min(1, Number(time) / dur)) : 0;
          shifterRef.current.percentagePlayed = perc;
          // resume if paused
          if (!isPlaying) {
            try { shifterRef.current.connect(pannerRef.current || gainRef.current); } catch(e){}
            setIsPlaying(true);
          }
          setSeekTime(time);
          return;
        } catch (e) { console.warn('shifter seek failed', e); }
      }

      if (!audioRef.current) return;
      // set currentTime then play; some browsers require play() after setting time
      audioRef.current.currentTime = Math.max(0, Number(time) || 0);
      const p = audioRef.current.play();
      if (p && typeof (p as any).then === 'function') {
        (p as any).then(() => setIsPlaying(true)).catch(()=>{});
      } else {
        setIsPlaying(true);
      }
      setSeekTime(time);
    } catch (e) { console.warn('seekAndPlay', e); }
  }
  const [showCover, setShowCover] = useState<boolean>(true);
  const [mediaFront, setMediaFront] = useState<'lyrics'|'cover'>('lyrics');
  const [lyricsRaw, setLyricsRaw] = useState<string | null>(null);
  const [lyricsTimed, setLyricsTimed] = useState<Array<{time:number;text:string}>|null>(null);
  const [lyricsVisible, setLyricsVisible] = useState<boolean>(false);
  const [lyricsMode, setLyricsMode] = useState<'static'|'synchronized'>('synchronized');
  const [lyricsIndex, setLyricsIndex] = useState<number>(0);
  const lyricsContainerRef = useRef<HTMLDivElement|null>(null);
  const [showDebug, setShowDebug] = useState<boolean>(false);

  // Lyrics timeupdate handler management
  const lyricsTimeHandlerRef = useRef<((e?: any)=>void)|null>(null);
  function attachLyricsTimeListener() {
    detachLyricsTimeListener();
    if (!lyricsTimed || lyricsTimed.length === 0) return;

    // If using PitchShifter, poll its timePlayed because it doesn't update the <audio> element
    if (shifterRef.current) {
      try {
        shifterPollRef.current = window.setInterval(() => {
          try {
            const sh = shifterRef.current;
            if (!sh) return;
            const t = (typeof sh.timePlayed === 'number') ? sh.timePlayed : (sh.sourcePosition && sh.sampleRate ? (sh.sourcePosition / sh.sampleRate) : 0);
            if (!seekingRef.current) setSeekTime(t);
            let idx = lyricsTimed.findIndex((l, i) => {
              const next = lyricsTimed[i+1];
              return t >= l.time && (!next || t < next.time);
            });
            if (idx === -1) {
              if (t < (lyricsTimed[0]?.time||0)) idx = 0; else idx = lyricsTimed.length -1;
            }
            setLyricsIndex(idx);
          } catch (e) { /* ignore */ }
        }, 200);
      } catch (e) { console.warn('shifter poll failed', e); }
      return;
    }

    const audio = audioRef.current;
    if (!audio) return;
    const handler = () => {
      try {
        const t = audio.currentTime;
        if (!seekingRef.current) setSeekTime(t);
        let idx = lyricsTimed.findIndex((l, i) => {
          const next = lyricsTimed[i+1];
          return t >= l.time && (!next || t < next.time);
        });
        if (idx === -1) {
          if (t < (lyricsTimed[0]?.time||0)) idx = 0; else idx = lyricsTimed.length -1;
        }
        setLyricsIndex(idx);
      } catch (e) { /* ignore */ }
    };
    lyricsTimeHandlerRef.current = handler;
    audio.addEventListener('timeupdate', handler);
  }
  function detachLyricsTimeListener() {
    // clear shifter poll if present
    if (shifterPollRef.current) {
      try { clearInterval(shifterPollRef.current); } catch(e){}
      shifterPollRef.current = null;
    }
    const audio = audioRef.current;
    const h = lyricsTimeHandlerRef.current;
    if (audio && h) audio.removeEventListener('timeupdate', h);
    lyricsTimeHandlerRef.current = null;
  }
  useEffect(() => {
    if (lyricsTimed && lyricsTimed.length) attachLyricsTimeListener(); else detachLyricsTimeListener();
    return () => detachLyricsTimeListener();
  }, [lyricsTimed]);

  useEffect(() => {
    // keep active line centered in the lyrics panel after the first few lines
    try {
      const container = lyricsContainerRef.current;
      const el = container ? container.querySelector(`#lyr-line-${lyricsIndex}`) : document.getElementById(`lyr-line-${lyricsIndex}`);
      if (!el || !container) return;
      const elEl = el as HTMLElement;

      // compute using bounding rects so offsets work even with nested elements
      const containerRect = container.getBoundingClientRect();
      const elRect = elEl.getBoundingClientRect();
      const distanceFromTop = elRect.top - containerRect.top;
      const desiredScrollTop = Math.max(0, container.scrollTop + distanceFromTop - (container.clientHeight / 2) + (elEl.clientHeight / 2));
      const maxScroll = Math.max(0, container.scrollHeight - container.clientHeight);
      const target = Math.min(maxScroll, desiredScrollTop);

      if (lyricsIndex > 2) {
        container.scrollTo({ top: target, behavior: 'smooth' });
      } else {
        // ensure visible for first few lines
        const elBottom = container.scrollTop + distanceFromTop + elEl.offsetHeight;
        const viewTop = container.scrollTop;
        const viewBottom = viewTop + container.clientHeight;
        if (distanceFromTop < 0 || elBottom > viewBottom) {
          container.scrollTo({ top: Math.max(0, container.scrollTop + distanceFromTop - 8), behavior: 'smooth' });
        }
      }
    } catch (e) { console.warn('lyrics scroll error', e); }
  }, [lyricsIndex]);

  // rename modal state
  const [renameModalOpen, setRenameModalOpen] = useState(false);
  const [renameValue, setRenameValue] = useState('');
  const [renameTarget, setRenameTarget] = useState<string | null>(null);
  const [autoNext, setAutoNext] = useState<boolean>(false);
  const [loopPlaylist, setLoopPlaylist] = useState<boolean>(false);
  const [isDragging, setIsDragging] = useState<boolean>(false);
  const dragCounter = useRef<number>(0);

  // load saved playlists once on mount (do not re-run on tracks change)
  useEffect(() => {
    const load = async () => {
      try {
        if ((window as any).electronAPI?.loadPlaylists) {
          const res = await (window as any).electronAPI.loadPlaylists();
          if (res && res.ok && Array.isArray(res.playlists)) {
            // Normalize saved playlists: convert tracks with file:// src into path entries, and strip any non-serializable fields
            const normalized = res.playlists.map((pl: any) => {
              const tracks = (pl.tracks || []).map((t: any) => {
                const tt: any = { id: t.id, name: t.name, path: t.path, src: t.src, cover: t.cover };
                // if src is a file:// URL, music:// URL and path missing, derive path
                if (!tt.path && tt.src && typeof tt.src === 'string') {
                  if (tt.src.startsWith('file://')) {
                    try { tt.path = decodeURI(tt.src.replace(/^file:\/\//, '')); } catch (e) { tt.path = tt.src.replace(/^file:\/\//, ''); }
                  } else if (tt.src.startsWith('music://')) {
                    try {
                      const u = new URL(tt.src);
                      let pth = decodeURIComponent(u.pathname || '');
                      // strip leading slashes that may precede Windows drives
                      if (pth.startsWith('/')) pth = pth.replace(/^\/+/, '');
                      tt.path = pth;
                    } catch (e) {
                      try { tt.path = decodeURIComponent(tt.src.replace(/^music:\/\//, '')); } catch (e2) { tt.path = tt.src.replace(/^music:\/\//, ''); }
                    }
                  }
                }
                return tt;
              });
              return { name: pl.name, tracks };
            });

            setPlaylists(normalized);
            const def = localStorage.getItem('defaultPlaylistName');
            const p = def ? normalized.find((pl: any) => pl.name === def) : (normalized[0] || null);
            if (p) {
              setSelectedPlaylistName(p.name);
              setTracks(p.tracks || []);
            }

            // recreate blob URLs for tracks that have a path (Electron environment)
            try {
              const api = (window as any).electronAPI;
              if (api?.readFile) {
                for (const pl of normalized) {
                  for (let idx = 0; idx < (pl.tracks || []).length; idx++) {
                    const t = pl.tracks[idx];
                    if (t && t.path) {
                      (async (track) => {
                        try {
                          const rf = await api.readFile(track.path);
                          if (rf && rf.ok && rf.data) {
                            const binary = atob(rf.data);
                            const len = binary.length;
                            const u8 = new Uint8Array(len);
                            for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
                            const blob = new Blob([u8], { type: rf.mime || 'application/octet-stream' });
                            const url = URL.createObjectURL(blob);
                            // update playlists state and tracks state if this playlist is selected
                            setPlaylists(prev => prev.map((pls:any) => ({ ...pls, tracks: (pls.tracks || []).map((pt:any) => pt.path === track.path ? { ...pt, src: url } : pt) })));
                            setTracks(cur => cur.map(pt => pt.path === track.path ? { ...pt, src: url } : pt));
                            setLogs(l=>[...l, `Recreated blob for saved track ${track.name}`]);

                                                // Try extracting cover art from the recreated blob and apply to state
                                                try {
                                                  const fileObj = (typeof File !== 'undefined') ? new File([blob], track.name, { type: rf.mime || 'application/octet-stream' }) : undefined;
                                                  const extractTarget: File | Blob = fileObj || blob;
                                                  const coverUrl = await extractCoverFromFile(extractTarget as any);
                                                  if (coverUrl) {
                                                    setPlaylists(prev => prev.map((pls:any) => ({ ...pls, tracks: (pls.tracks || []).map((pt:any) => pt.path === track.path ? { ...pt, cover: coverUrl } : pt) })));
                                                    setTracks(cur => cur.map(pt => pt.path === track.path ? { ...pt, cover: coverUrl } : pt));
                                                    setLogs(l=>[...l, `Extracted cover for saved track ${track.name}`]);
                                                  } else {
                                                    setLogs(l=>[...l, `No cover found in saved track ${track.name}`]);
                                                  }
                                                } catch (covErr) {
                                                  setLogs(l=>[...l, `cover extract failed for saved track ${track.name}: ${String(covErr)}`]);
                                                }

                                              } else {
                                                setLogs(l=>[...l, `readFile failed for saved track ${track?.name}: ${rf?.error || 'unknown'}`]);
                                              }
                                            } catch (err) { setLogs(l=>[...l, `readFile exception for saved track ${track?.name}: ${String(err)}`]); }
                                          })(t);
                                        }
                  }
                }
              }
            } catch (e) { setLogs(l=>[...l, `recreate on load error: ${String(e)}`]); }

            return;
          }
        }
      } catch (e) { console.warn('loadPlaylists electron failed', e); }
      // fallback to localStorage
      try {
        const raw = localStorage.getItem('playlists');
        if (raw) {
          const arr = JSON.parse(raw || '[]');
          if (Array.isArray(arr)) {
            setPlaylists(arr);
            const def = localStorage.getItem('defaultPlaylistName');
            const p = def ? arr.find((pl: any) => pl.name === def) : (arr[0] || null);
            if (p) { setSelectedPlaylistName(p.name); setTracks(p.tracks || []); }
          }
        }
      } catch (e) { /* ignore */ }
    };
    load();
  }, []);

  // when playlists change and no selection, default to first playlist
  useEffect(() => {
    if ((!selectedPlaylistName || selectedPlaylistName === '') && playlists && playlists.length > 0) {
      const p = playlists[0];
      setSelectedPlaylistName(p.name);
      setTracks(p.tracks || []);
    }
  }, [playlists]);

  // keyboard delete handler
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Delete' && selected != null) {
        const t = tracks[selected];
        if (t && t.src && t.src.startsWith('blob:')) URL.revokeObjectURL(t.src);
        setTracks(prev => prev.filter((_, i) => i !== selected));
        setSelected(null);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [selected, tracks]);

  // load preferences from localStorage
  useEffect(() => {
    try {
      const sv = localStorage.getItem('showCover');
      setShowCover(sv === null ? true : sv === 'true');
      const an = localStorage.getItem('autoNext');
      setAutoNext(an === 'true');
      const lp = localStorage.getItem('loopPlaylist');
      setLoopPlaylist(lp === 'true');
      const ab = localStorage.getItem('autoGenerateBacking');
      setAutoGenerateBacking(ab === 'true');
    } catch (e) { /* ignore */ }
  }, []);

  // show B button only when selected track has an existing backing file
  useEffect(() => {
    const check = async () => {
      if (selected === null) return;
      const t = tracks[selected];
      if (!t || !t.path) return;
      const pth = t.path.replace(/\\/g,'/');
      const dir = pth.replace(/\/[^^/]*$/, '');
      const base = (pth.split('/').pop() || '').replace(/\.[^/.]+$/, '');
      const candMp3 = dir + '/' + base + '_backingtrack.mp3';
      const candWav = dir + '/' + base + '_backingtrack.wav';
      try {
        const api = (window as any).electronAPI;
        if (!api?.stat) return;
        const s1 = await api.stat(candMp3);
        if (s1 && s1.ok && s1.isFile) { setBackingAvailableMap(m => ({ ...m, [t.id]: true })); return; }
        const s2 = await api.stat(candWav);
        if (s2 && s2.ok && s2.isFile) { setBackingAvailableMap(m => ({ ...m, [t.id]: true })); return; }
        setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
      } catch (e) {
        setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
      }
    };
    check();
  }, [selected, tracks]);

  // attach ended handler for autoplay/loop
  useEffect(() => {
    const a = audioRef.current;
    if (!a) return;
    const onEnded = () => {
      if (!autoNext) return;
      const idx = current ?? -1;
      const next = idx + 1;
      if (next < tracks.length) {
        playIndex(next);
      } else if (loopPlaylist && tracks.length > 0) {
        playIndex(0);
      }
    };
    a.addEventListener('ended', onEnded);
    return () => a.removeEventListener('ended', onEnded);
  }, [audioRef, autoNext, loopPlaylist, current, tracks]);

  async function extractCoverFromFile(file: File | Blob): Promise<string | null> {
    try { setLogs(l=>[...l, `extractCoverFromFile start for ${(file as any).name || 'blob'}`]); } catch(e){}
    try {
      // ensure Buffer polyfill for browser builds
      if (typeof (window as any).Buffer === 'undefined') {
        try {
          const bufmod = await import('buffer');
          (window as any).Buffer = bufmod.Buffer;
          setLogs(l=>[...l, 'polyfilled Buffer']);
        } catch (bufErr) {
          console.warn('buffer polyfill failed', bufErr);
          setLogs(l=>[...l, 'buffer polyfill failed: ' + String(bufErr)]);
        }
      }
      const mm = await import('music-metadata-browser');
      const metadata = await (mm as any).parseBlob(file);
      // detailed logging for diagnosis
      try { setLogs(l=>[...l, `metadata common keys: ${Object.keys(metadata.common || {}).join(',')}; pictures:${(metadata.common?.picture?.length)||0}`]); } catch(e){}
      console.log('music-metadata metadata', metadata);
      const pics = metadata?.common?.picture;
      if (pics && pics.length > 0) {
        const pic = pics[0];
        const blob = new Blob([pic.data as any], { type: pic.format || 'image/jpeg' });
        return URL.createObjectURL(blob);
      }
    } catch (e) {
      console.warn('music-metadata-browser parse failed', e);
      try { setLogs(l=>[...l, 'parse failed: ' + String(e)]); } catch(e){}
    }
    return null;
  }

  function parseTimestampedLyrics(text: string): Array<{time:number;text:string}> {
    const out: Array<{time:number;text:string}> = [];
    if (!text) return out;
    const lines = text.split(/\r?\n/);
    const timeRe = /\[?(\d{1,2}):(\d{2})(?:[.:](\d{1,3}))?\]?\s*(.*)/;
    for (const line of lines) {
      const m = line.match(timeRe);
      if (m) {
        const mins = parseInt(m[1], 10);
        const secs = parseInt(m[2], 10);
        const ms = m[3] ? parseInt((m[3] + '00').slice(0,3), 10) : 0;
        const time = mins * 60 + secs + ms / 1000;
        const textPart = m[4] || '';
        out.push({ time, text: textPart });
      }
    }
    // sort by time
    out.sort((a,b)=>a.time-b.time);
    return out;
  }

  async function getLyricsForTrack(t: Track): Promise<boolean> {
    try {
      const api = (window as any).electronAPI;
      setLyricsRaw(null);
      setLyricsTimed(null);
      // Ask main process (preferred for files on disk)
      if (t.path && api?.getLyrics) {
        try {
          const res = await api.getLyrics(t.path);
          if (res && res.ok) {
            setLyricsRaw(res.lyrics || null);
            if (res.timed && Array.isArray(res.timed) && res.timed.length) {
              setLyricsTimed(res.timed.map((it:any)=>({ time: Number(it.time)||0, text: String(it.text||'') })));
              return true;
            } else {
              // attempt to parse timestamped lines from returned lyrics text
              if (res.lyrics && typeof res.lyrics === 'string') {
                const parsed = parseTimestampedLyrics(res.lyrics);
                if (parsed.length) { setLyricsTimed(parsed); return true; }
              }
              setLyricsTimed(null);
              return false;
            }
          }
        } catch (e) { /* ignore */ }
      }

      // try reading from File/blob using music-metadata-browser
      try {
        if (t.file) {
          const mm = await import('music-metadata-browser');
          const meta = await (mm as any).parseBlob(t.file);
          const lyr = meta?.common?.lyrics;
          if (lyr && lyr.length) { setLyricsRaw(lyr.join('\n')); setLyricsTimed(null); // attempt parse
            const parsed = parseTimestampedLyrics(lyr.join('\n'));
            if (parsed.length) { setLyricsTimed(parsed); return true; }
            return false; }
        }
      } catch (e) { /* ignore */ }

      // fallback: if path available, read file via electron readFile and parse blob (client-side parse)
      try {
        if (t.path && api?.readFile) {
          const rf = await api.readFile(t.path);
          if (rf && rf.ok && rf.data) {
            const binary = atob(rf.data);
            const len = binary.length;
            const u8 = new Uint8Array(len);
            for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
            const blob = new Blob([u8], { type: rf.mime || 'application/octet-stream' });
            const mm = await import('music-metadata-browser');
            const meta = await (mm as any).parseBlob(blob);
            const lyr = meta?.common?.lyrics;
            if (lyr && lyr.length) { setLyricsRaw(lyr.join('\n')); setLyricsTimed(null); const parsed = parseTimestampedLyrics(lyr.join('\n'));
            if (parsed.length) { setLyricsTimed(parsed); return true; } return false; }
          }
        }
      } catch (e) { /* ignore */ }

      // nothing found
      setLyricsRaw(null);
      setLyricsTimed(null);
      return false;
    } catch (e) { setLyricsRaw(null); setLyricsTimed(null); return false; }
  }

  async function generateBackingForTracks(list: Track[]) {
    const api = (window as any).electronAPI;
      const results: { id: string; name: string; ok: boolean; path?: string; error?: string }[] = [];
      setLogs(l => [...l, `generateBackingForTracks: called for ${list.length} tracks`]);
      try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`generateBackingForTracks called for ${list.length} tracks`); } catch(e){}
      if (!api?.generateBacking) {
        setLogs(l => [...l, 'generateBacking API not available on window.electronAPI']);
        try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog('generateBacking API not available on window.electronAPI'); } catch(e){}
        // mark as unavailable
        for (const t of list) setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
        return;
      }
    const tasks: Promise<void>[] = [];
    for (const t of list) {
        const task = (async () => {
          try {
            let targetPath: string | undefined = undefined;
            if (t.path) targetPath = t.path;
            else if (t.file && api?.writeTempFile) {
              try {
                const arrBuf = await (t.file as File).arrayBuffer();
                const u8 = new Uint8Array(arrBuf);
                let binary = '';
                for (let i = 0; i < u8.length; i++) binary += String.fromCharCode(u8[i]);
                const b64 = btoa(binary);
                const wt = await api.writeTempFile(t.name, b64);
                if (wt && wt.ok && wt.path) targetPath = wt.path;
                else {
                  results.push({ id: t.id, name: t.name, ok: false, error: wt?.error || 'write temp failed' });
                  setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
                  return;
                }
              } catch (we) {
                results.push({ id: t.id, name: t.name, ok: false, error: String(we) });
                setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
                return;
              }
            } else {
              // no path and no file -> cannot generate
              results.push({ id: t.id, name: t.name, ok: false, error: 'no source path' });
              setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
              return;
            }

            if (!targetPath) {
              results.push({ id: t.id, name: t.name, ok: false, error: 'no target path' });
              setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
              return;
            }

            setLogs(l => [...l, `generateBacking: invoking for ${t.name} -> ${targetPath}`]);
            try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`generateBacking: invoking for ${t.name} -> ${targetPath}`); } catch(e){}
            const res = await api.generateBacking(targetPath);
            if (res && res.ok && res.path) {
              results.push({ id: t.id, name: t.name, ok: true, path: res.path });
              setBackingAvailableMap(m => ({ ...m, [t.id]: true }));
              setLogs(l => [...l, `generateBacking succeeded for ${t.name}: ${res.path}`]);
              try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`generateBacking succeeded for ${t.name}: ${res.path}`); } catch(e){}
            } else {
              results.push({ id: t.id, name: t.name, ok: false, error: res?.error || 'no output' });
              setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
              setLogs(l => [...l, `generateBacking failed for ${t.name}: ${res?.error || 'no output'}`]);
              try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`generateBacking failed for ${t.name}: ${res?.error || 'no output'}`); } catch(e){}
            }
          } catch (e: any) {
            results.push({ id: t.id, name: t.name, ok: false, error: String(e) });
            setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
          }
        })();
        tasks.push(task);
      }
      if (tasks.length === 0) return;
      await Promise.all(tasks);
      const okCount = results.filter(r => r.ok).length;
      const failCount = results.length - okCount;
      setLogs(l => [...l, `Auto-generate backing finished: ${okCount} succeeded, ${failCount} failed`]);
      try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Auto-generate backing finished: ${okCount} succeeded, ${failCount} failed`); } catch(e){}
      if (okCount > 0) alert(`Backing track ready: ${okCount} succeeded${failCount>0?`, ${failCount} failed`:''}`);
      else alert(`No backing tracks produced (${failCount} attempts failed)`);
    }

  function addFilesFromFileList(fileList: FileList) {
    const arr: Track[] = [];
    for (let i = 0; i < fileList.length; i++) {
      const f = fileList.item(i)! as any;
      const name = f.name;
      const p = (f as any).path || undefined;
          // Skip backing tracks if user doesn't want them mixed into playlists
          if (name.match(/_backingtrack\.(mp3|wav)$/i)) continue;
          if (!name.match(/\.(mp3|flac)$/i)) continue;
          // Prefer using blob URLs for playback (works in browser and Electron) even if a file.path exists.
          const src = URL.createObjectURL(f);
          const id = p ? `path:${p}` : `${name}:${f.size}:${f.lastModified}`;
          const track: Track = { id, name, src, file: f };
          if (p) track.path = p;
          arr.push(track);
        }

    setTracks(prev => {
      const newTracks = [...prev, ...arr];
      setLogs(l=>[...l, `Added ${arr.length} files from file input`]);
      try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Added ${arr.length} files from file input`); } catch (e) {}

      // If running in Electron, and we have file paths, read from disk to create stable blob URLs
      const api = (window as any).electronAPI;
      if (api?.readFile) {
        for (const t of arr) {
          if (t.path) {
            (async () => {
              try {
                const res = await api.readFile(t.path);
                if (res && res.ok && res.data) {
                  const binary = atob(res.data);
                  const len = binary.length;
                  const u8 = new Uint8Array(len);
                  for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
                  const blob = new Blob([u8], { type: res.mime || 'application/octet-stream' });
                  const url = URL.createObjectURL(blob);
                            // Update track src; if this track is currently playing, swap src on the audio element while preserving time/play state
                            setTracks(currentTracks => {
                              const updated = currentTracks.map(ct => ct.id === t.id ? { ...ct, src: url } : ct);
                              try {
                                const curIdx = current;
                                if (curIdx != null) {
                                  const curTrack = currentTracks[curIdx];
                                  if (curTrack && curTrack.id === t.id && audioRef.current) {
                                    const wasPlaying = !audioRef.current.paused;
                                    const curTime = audioRef.current.currentTime || 0;
                                    try { audioRef.current.src = url; } catch(e) { /* ignore */ }
                                    try { audioRef.current.currentTime = Math.max(0, Math.min(curTime, audioRef.current.duration || curTime)); } catch(e) { }
                                    if (wasPlaying) {
                                      try { const p = audioRef.current.play(); if (p && typeof (p as any).then === 'function') p.catch(()=>{}); } catch(e) {}
                                    }
                                  }
                                }
                              } catch(e) {
                                console.warn('preserve audio src swap failed', e);
                              }
                              return updated;
                            });
                            setLogs(l=>[...l, `readFile created blob for ${t.name}`]);
                          } else {
                            setLogs(l=>[...l, `readFile failed for ${t.name}: ${res?.error || 'unknown'}`]);
                          }
                        } catch (err) {
                          setLogs(l=>[...l, `readFile exception ${String(err)}`]);
                        }
                      })();
                    }
        }
      }

      // attempt to extract cover art for newly added files (browser blobs)
      for (const t of newTracks) {
        if (t.file && !t.cover) {
          // kick off extraction but do not await here
          extractCoverFromFile(t.file).then(url => {
            if (url) {
              setLogs(l => [...l, `extracted cover for ${t.name}`]);
              setTracks(currentTracks => currentTracks.map(ct => ct.id === t.id ? { ...ct, cover: url } : ct));
            } else {
              setLogs(l => [...l, `no cover in ${t.name}`]);
            }
          }).catch(err => {
            console.warn('extract cover failed', err);
            setLogs(l => [...l, `cover extract error ${t.name}: ${String(err)}`]);
          });
        }
      }

      return newTracks;
    });

    // kick off auto-generate if enabled
    if (autoGenerateBacking) {
      generateBackingForTracks(arr);
    }
  }


    async function addFilesFromPathList(paths: string[]) {
      const arr: Track[] = [];
      const api = (window as any).electronAPI;
      for (const p of paths) {
        const name = p.split(/[/\\]/).pop() || p;
              // Skip backing tracks (already-generated accompaniment files)
              if (name.match(/_backingtrack\.(mp3|wav)$/i)) continue;
              if (!name.match(/\.(mp3|flac)$/i)) continue;
              const id = `path:${p}`;
              // Prefer music:// protocol in Electron to stream directly with range support
              const src = api ? `music://local/${encodeURIComponent(p)}` : undefined;
              arr.push({ id, name, path: p, src });
            }

      setTracks(prev => {
        const newTracks = [...prev, ...arr];
        setLogs(l=>[...l, `Added ${arr.length} files from path list`]);
        try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Added ${arr.length} files from path list: ${arr.map(a=>a.name).join(',')}`); } catch (e) {}
        console.log('addFilesFromPathList added', arr.map(a=>a.name));
        return newTracks;
      });

      // If music protocol not available, fall back to reading and creating blob URLs
      if (!api?.readFile) return;

      for (const t of arr) {
        (async () => {
          try {
            const statRes = await api.stat?.(t.path);
            if (statRes && statRes.ok && statRes.isFile) {
              // nothing else needed when music:// is used
              return;
            }
          } catch(_) {}

          try {
            const pathKey = t.path || '';
            const reqId = ((readRequestIdRef.current[pathKey] || 0) + 1);
            readRequestIdRef.current[pathKey] = reqId;

            const res = await api.readFile(t.path);
            if (readRequestIdRef.current[pathKey] !== reqId) {
              setLogs(l=>[...l, `stale readFile result ignored for ${t.path}`]);
            } else if (res && res.ok && res.data) {
              const binary = atob(res.data);
              const len = binary.length;
              const u8 = new Uint8Array(len);
              for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
              const blob = new Blob([u8], { type: res.mime || 'application/octet-stream' });
              const url = URL.createObjectURL(blob);
              // create a File object if supported (useful for chrome APIs)
              let fileObj: File | undefined = undefined;
              try { fileObj = new File([blob], t.name, { type: res.mime || 'application/octet-stream' }); } catch (e) { /* ignore if not supported */ }
                          // If current track matches, swap audio.src while preserving time/play state
                          setTracks(currentTracks => {
                            const updated = currentTracks.map(ct => ct.id === t.id ? { ...ct, src: url, file: fileObj } : ct);
                            try {
                              const curIdx = current;
                              if (curIdx != null) {
                                const curTrack = currentTracks[curIdx];
                                if (curTrack && curTrack.id === t.id && audioRef.current) {
                                  const wasPlaying = !audioRef.current.paused;
                                  const curTime = audioRef.current.currentTime || 0;
                                  try { audioRef.current.src = url; } catch(e) { /* ignore */ }
                                  try { audioRef.current.currentTime = Math.max(0, Math.min(curTime, audioRef.current.duration || curTime)); } catch(e) { }
                                  if (wasPlaying) {
                                    try { const p = audioRef.current.play(); if (p && typeof (p as any).then === 'function') p.catch(()=>{}); } catch(e) {}
                                  }
                                }
                              }
                            } catch(e) { console.warn('preserve audio src swap failed', e); }
                            return updated;
                          });
                          setLogs(l=>[...l, `Created blob for ${t.name}`]);
                          try { api.appendLog && api.appendLog(`Created blob for ${t.name}`); } catch(e){}
                          // try extract cover using the File object if available, otherwise use the Blob
                          const extractTarget: File | Blob = fileObj || blob;
                          extractCoverFromFile(extractTarget).then(urlCover => {
                            if (urlCover) setTracks(currentTracks => currentTracks.map(ct => ct.id === t.id ? { ...ct, cover: urlCover } : ct));
                          }).catch(err => { setLogs(l=>[...l, `cover extract error ${t.name}: ${String(err)}`]); });
                        } else {
                          setLogs(l=>[...l, `readFile failed for ${t.path}: ${res?.error || 'unknown'}`]);
                        }
          } catch (err) {
            setLogs(l=>[...l, `readFile exception ${String(err)}`]);
          }
        })();
      }

      // kick off auto-generate if enabled for path-added tracks
      if (autoGenerateBacking) {
        generateBackingForTracks(arr);
      }
    }

  async function onFiles(e: React.ChangeEvent<HTMLInputElement>) {
    if (!e.target.files) return;
    addFilesFromFileList(e.target.files);
  }

  async function onFolder(e: React.ChangeEvent<HTMLInputElement> | undefined) {
      // Prefer Electron folder chooser when available to avoid browser "upload all files" prompt
      if ((window as any).electronAPI?.chooseFolder) {
        try {
          const res = await (window as any).electronAPI.chooseFolder();
          if (res && res.canceled === false && Array.isArray(res.paths)) {
            for (const p of res.paths) {
              const r = await (window as any).electronAPI.readdirRecursive(p);
              if (r && r.ok && Array.isArray(r.files)) {
                const files = r.files.filter((f: string) => f.match(/\.(mp3|flac)$/i));
                await addFilesFromPathList(files);
              }
            }
          }
        } catch (err) { console.warn('chooseFolder failed', err); }
        return;
      }
      if (!e || !e.target || !e.target.files) return;
      // webkitdirectory gives all files inside
      addFilesFromFileList(e.target.files);
    }

  async function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    // reset drag counter/state reliably
    dragCounter.current = 0;
    setIsDragging(false);
    const dt = e.dataTransfer;
    if (!dt) return;
    if (dt.files && dt.files.length > 0) {
      addFilesFromFileList(dt.files);
      return;
    }
  }

  function onDragOver(e: React.DragEvent) { e.preventDefault(); }
  function onDragEnter(e: React.DragEvent) { e.preventDefault(); dragCounter.current++; if (dragCounter.current > 0) setIsDragging(true); }
  function onDragLeave(e: React.DragEvent) { e.preventDefault(); dragCounter.current = Math.max(0, dragCounter.current - 1); if (dragCounter.current === 0) setIsDragging(false); }

  function nextTrack() {
    const idx = current ?? -1;
    let next = idx + 1;
    if (next >= tracks.length) {
      if (loopPlaylist && tracks.length > 0) next = 0;
      else return;
    }
    playIndex(next);
  }

  function prevTrack() {
    const idx = current ?? 0;
    let prev = idx - 1;
    if (prev < 0) {
      if (loopPlaylist && tracks.length > 0) prev = tracks.length - 1;
      else return;
    }
    playIndex(prev);
  }

  async function setAudioSourceAndPlay(newSrc: string, idx: number) {
    try {
      if (shifterRef.current) {
        try { shifterRef.current.disconnect(); } catch(e) {}
        shifterRef.current = null as any;
      }
      if (audioRef.current) {
        try { audioRef.current.pause(); } catch(e) {}
        audioRef.current.src = newSrc;
        try { audioRef.current.currentTime = 0; } catch(e) {}
        await (audioCtxRef.current?.state === 'suspended' ? audioCtxRef.current.resume() : Promise.resolve());
        try { await audioRef.current.play(); } catch(e) { console.warn('play failed', e); }
        setIsPlaying(true);
        setCurrent(idx);
      }
    } catch(e) { console.warn('setAudioSourceAndPlay failed', e); }
  }

  async function playIndex(i: number) {
    const t = tracks[i];
    if (!t) return;
    // Stop any prior playback sources to avoid multiple progress updates racing
    try {
      if (shifterRef.current) {
        try { shifterRef.current.disconnect(); } catch(e){}
        shifterRef.current = null as any;
      }
    } catch(e) {}
    try { if (audioRef.current) { try { audioRef.current.pause(); } catch(e){} } } catch(e) {}
    setIsPlaying(false);

    let src: string | undefined;

    // If backingActive is set, prefer backing file in the same folder when available
    try {
      const api = (window as any).electronAPI;
      if (t.path && t.backingActive && api?.stat) {
        const pth = t.path.replace(/\\/g,'/');
        const dir = pth.replace(/\/[^\/]*$/,'');
        const base = (pth.split('/').pop() || '').replace(/\.[^/.]+$/, '');
        const candMp3 = dir + '/' + base + '_backingtrack.mp3';
        const candWav = dir + '/' + base + '_backingtrack.wav';
        try {
          const s1 = await api.stat(candMp3);
          if (s1 && s1.ok && s1.isFile) {
            src = `music://local/${encodeURIComponent(candMp3)}`;
          } else {
            const s2 = await api.stat(candWav);
            if (s2 && s2.ok && s2.isFile) src = `music://local/${encodeURIComponent(candWav)}`;
          }
        } catch(e) {
          // ignore and fallback to normal src resolution
        }
      }
    } catch(e) {}

    if (!src) {
      if (t.src) src = t.src;
      else if (t.path) {
        const api = (window as any).electronAPI;
        if (api) {
          // prefer streaming via music:// protocol which supports range requests
          src = `music://local/${encodeURIComponent(t.path)}`;
        } else {
          // normalize Windows paths into file URL (browser only)
          const p = t.path.replace(/\\/g, '/').replace(/^\/+/, '');
          src = `file:///${encodeURI(p)}`;
        }
      }
    }

    // If running in Electron and music protocol isn't available for some reason, keep previous readFile fallback
    try {
      const api = (window as any).electronAPI;
      if (src && src.startsWith('file://') && api?.readFile) {
        try {
            // create/read guard id for this path to avoid applying stale blobs
            const pathKey = t.path || '';
            const reqId = ((readRequestIdRef.current[pathKey]||0) + 1);
            readRequestIdRef.current[pathKey] = reqId;

            const res = await api.readFile(t.path);

            // if another read started after this one, ignore result
            if (readRequestIdRef.current[pathKey] !== reqId) {
              setLogs(l=>[...l, `stale recreate readFile result ignored for ${t.path}`]);
            } else if (res && res.ok && res.data) {
              const binary = atob(res.data);
              const len = binary.length;
              const u8 = new Uint8Array(len);
              for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
              const blob = new Blob([u8], { type: res.mime || 'application/octet-stream' });
              const url = URL.createObjectURL(blob);
              src = url;
              setTracks(prev => prev.map((pt, idx) => idx === i ? { ...pt, src: url } : pt));
            } else {
              setLogs(l=>[...l, `readFile failed for ${t.path}: ${res?.error || 'unknown'}`]);
            }
        } catch(err) {
          setLogs(l=>[...l, `readFile exception ${String(err)}`]);
        }
      }
    } catch(e) { }

    if (!src) return;
    // If blob URL fails (HMR or URL revoked), recreate it from the original File if available.
    try {
      if (src.startsWith('blob:')) {
        // If we have the original File object, recreate blob URL to ensure it's valid
        if (t.file) {
          try {
            const newUrl = URL.createObjectURL(t.file);
            src = newUrl;
            setTracks(prev => prev.map((pt, idx) => idx === i ? { ...pt, src: newUrl } : pt));
            setLogs(l=>[...l, `Recreated blob URL for ${t.name}`]);
            try{ (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Recreated blob URL for ${t.name}`); }catch{}
          } catch (e) { setLogs(l=>[...l, `recreate blob error ${String(e)}`]); }
        } else if (t.path && (window as any).electronAPI?.readFile) {
          // As a last resort, read file again from disk and create blob
          try {
            const pathKey = t.path || '';
            const reqId = ((readRequestIdRef.current[pathKey] || 0) + 1);
            readRequestIdRef.current[pathKey] = reqId;

            const res = await (window as any).electronAPI.readFile(t.path);
            if (readRequestIdRef.current[pathKey] !== reqId) {
              setLogs(l=>[...l, `stale recreate readFile result ignored for ${t.path}`]);
            } else if (res && res.ok && res.data) {
              const binary = atob(res.data);
              const len = binary.length;
              const u8 = new Uint8Array(len);
              for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
              const blob = new Blob([u8], { type: res.mime || 'application/octet-stream' });
              const url = URL.createObjectURL(blob);
              src = url;
              setTracks(prev => prev.map((pt, idx) => idx === i ? { ...pt, src: url } : pt));
              setLogs(l=>[...l, `Recreated blob URL from disk for ${t.name}`]);
            }
          } catch (e) { setLogs(l=>[...l, `readFile recreate error ${String(e)}`]); }
        }
      }
    } catch(e) { /* ignore */ }

    // If cover missing for this track, attempt to extract from file/blob now so UI can show it during playback
    try {
      if (!t.cover) {
        const api = (window as any).electronAPI;
        let extractTarget: File | Blob | undefined;
        if (src && src.startsWith('blob:') && t.file) {
          extractTarget = t.file;
        } else if (t.path && api?.readFile) {
          try {
            const rf = await api.readFile(t.path);
            if (rf && rf.ok && rf.data) {
              const binary = atob(rf.data);
              const len = binary.length;
              const u8 = new Uint8Array(len);
              for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
              const blob = new Blob([u8], { type: rf.mime || 'application/octet-stream' });
              extractTarget = blob;
              try { t.file = new File([blob], t.name, { type: rf.mime || 'application/octet-stream' }); } catch(e) { /* ignore */ }
            }
          } catch(e) { /* ignore */ }
        }
        if (extractTarget) {
          const cov = await extractCoverFromFile(extractTarget as any);
          if (cov) {
            setTracks(prev => prev.map((pt, idx) => idx === i ? { ...pt, cover: cov } : pt));
            setLogs(l=>[...l, `Extracted cover for ${t.name} on play`]);
          }
        }
      }
    } catch(e) { setLogs(l=>[...l, `cover extract on play error: ${String(e)}`]); }

    console.log('Attempting play', { index: i, track: t, src });
    try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Attempting play index=${i} name=${t.name}`); } catch (e) { try{ setLogs(l=>[...l, 'appendLog failed: ' + String(e)]); } catch{} }
    if (src.startsWith('file://') && !(window as any).electronAPI) {
      // In browser contexts file:// is not allowed for security reasons.
      alert('Cannot play local file paths in the browser. Use "Add Files" so the file is loaded as a blob, or run the Electron app.');
      return;
    }

    if (playLockRef.current) {
      setLogs(l => [...l, `Play request ignored due to ongoing play operation`]);
      return;
    }
    playLockRef.current = true;

    // Ensure AudioContext and nodes exist
    try {
      if (!audioCtxRef.current) {
        const C = (window as any).AudioContext || (window as any).webkitAudioContext;
        const ctx = new C();
        audioCtxRef.current = ctx;
        const panner = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
        pannerRef.current = panner;
        const gain = ctx.createGain();
        gainRef.current = gain;
        if (panner) { panner.connect(gain); }
        gain.connect(ctx.destination);
        try { gain.gain.value = volume; } catch(e){}
      }
    } catch(e) {
      console.warn('AudioContext init failed', e);
    }

    // Attempt to use soundtouchjs PitchShifter for tempo-preserving pitch changes. If unavailable, fallback to <audio> playback.
    let usedPitchShifter = false;
    try {
      const stMod = await import('soundtouchjs');
      const PitchShifter = (stMod as any).PitchShifter;
      if (PitchShifter && audioCtxRef.current && gainRef.current) {
        try {
          // fetch and decode source into AudioBuffer
          const arr = await fetch(src).then(r => r.arrayBuffer());
          const audioBuf = await audioCtxRef.current.decodeAudioData(arr);
          // clean up any previous shifter
          try { shifterRef.current?.disconnect(); } catch(e){}
          const shifter = new (PitchShifter as any)(audioCtxRef.current, audioBuf, 16384, () => { try { if (autoNext) { nextTrack(); } else { setIsPlaying(false); } } catch(e) {} });
          shifter.tempo = 1;
          shifter.pitchSemitones = transpose || 0;
          // connect to existing gain/panner chain
          if (pannerRef.current) shifter.connect(pannerRef.current); else shifter.connect(gainRef.current);

          // wire up progress events
          shifter.on('play', (detail: any) => {
            try { if (!seekingRef.current) setSeekTime(detail.timePlayed); } catch(e){}
            try { setDuration(shifter.duration || detail.duration || duration); } catch(e){}
          });

          // start playback
          await (audioCtxRef.current.state === 'suspended' ? audioCtxRef.current.resume() : Promise.resolve());
          shifterRef.current = shifter;
          setCurrent(i);
          setIsPlaying(true);
          // Attach lyrics poller when pitch shifter starts so lyrics/seek stay in sync
          try { attachLyricsTimeListener(); } catch(e) { /* ignore */ }
          // Prefetch lyrics for this track so UI shows lyrics when using PitchShifter
          try {
            const found = await getLyricsForTrack(t);
            setLyricsMode(found ? 'synchronized' : 'static');
          } catch (e) { console.warn('getLyricsForTrack failed', e); }
          setLogs(l=>[...l, `PitchShifter playback started for ${t.name}`]);
          usedPitchShifter = true;
        } catch (err) {
          console.warn('PitchShifter init failed', err);
          setLogs(l=>[...l, `PitchShifter failed: ${String(err)}`]);
        }
      }
    } catch (e) {
      // dynamic import failed - not fatal, fall back to audio element
      console.log('soundtouchjs not available, falling back to <audio> element');
    }

    if (!usedPitchShifter && audioRef.current) {
      // Fallback: keep existing <audio> element playback
      try {
        // basic support check by extension
        const ext = (t.name || '').split('.').pop()?.toLowerCase();
        const mime = ext === 'mp3' ? 'audio/mpeg' : ext === 'flac' ? 'audio/flac' : '';
        try {
          const can = (mime && audioRef.current.canPlayType) ? audioRef.current.canPlayType(mime) : '';
          setLogs(l=>[...l, `canPlayType(${mime})=${can}`]);
        } catch (e) { setLogs(l=>[...l, `canPlayType check error: ${String(e)}`]); }

        // Reset position to start if possible.
        try { audioRef.current.currentTime = 0; } catch (e) {}
        // clear previous sources
        audioRef.current.removeAttribute('src');
        while (audioRef.current.firstChild) audioRef.current.removeChild(audioRef.current.firstChild as Node);
        if (mime) {
          const srcEl = document.createElement('source');
          srcEl.src = src;
          srcEl.type = mime;
          audioRef.current.appendChild(srcEl);
        } else {
          audioRef.current.src = src;
        }
        audioRef.current.load();
        const p = audioRef.current.play();
        if (p !== undefined && typeof (p as any).then === 'function') {
          (p as any).then(async () => { setCurrent(i); try{ (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Playback started index=${i} name=${t.name}`); }catch{}
                          // prefetch lyrics when playback starts
                          try { const found = await getLyricsForTrack(t); if (found) setLyricsMode('synchronized'); else setLyricsMode('static'); } catch(e) {}
                        })
                      .catch((err: any) => {
              console.error('Playback failed', err);
              setLogs(l=>[...l, 'Playback failed: ' + String((err as any))]);
                            try{ (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Playback failed index=${i} error=${String((err as any))}`); }catch{}
              // Ignore benign aborts caused by an immediate pause interrupting play()
                            const msg = (err && (((err as any).message) || ((err as any).name) || String(err))).toString();
              if (!/interrupted|aborted|abort/i.test(msg)) {
                              alert('Playback failed: ' + String((err as any)));
              } else {
                setLogs(l=>[...l, 'Ignored abort/interrupted play(): ' + msg]);
              }
            }).finally(() => { playLockRef.current = false; });
        } else {
          setCurrent(i);
          playLockRef.current = false;
        }
      } catch (err) {
        console.error('play error', err);
        setLogs(l=>[...l, 'play error: ' + String((err as any))]);
                alert('Playback failed: ' + String((err as any)));
      } finally {
        // ensure lock is released in case of synchronous errors
        playLockRef.current = false;
      }
    } else {
      // started via PitchShifter
      playLockRef.current = false;
    }
  }

  function playSelected() {
    const idx = selected ?? current;
    if (idx === null || idx === undefined) return;
    playIndex(idx);
  }

  function getNextPlaylistName() {
      // names like playlist1, playlist2 (case-insensitive)
      const used = new Set(playlists.map(p => (p.name || '').toLowerCase()));
      let max = 0;
      for (const n of used) {
        const m = n.match(/^playlist(\d+)$/i);
        if (m) {
          const v = parseInt(m[1], 10);
          if (!isNaN(v) && v > max) max = v;
        }
      }
      let candidate: string;
      do {
        candidate = `playlist${max + 1}`;
        max++;
      } while (used.has(candidate.toLowerCase()));
      return candidate;
    }

    async function savePlaylist() {
      // If user has selected an existing playlist, overwrite it.
      // Otherwise auto-generate a new sequential name like playlist1, playlist2.
      let name = selectedPlaylistName || '';
      const isExisting = !!playlists.find(p => p.name === name);
      if (!isExisting) {
        name = getNextPlaylistName();
      }

      // create a serializable copy of tracks (strip File and other non-cloneable objects)
      const serializableTracks = tracks.map(t => ({ id: t.id, name: t.name, path: t.path, src: t.src, cover: t.cover }));

      if ((window as any).electronAPI?.savePlaylist) {
        try {
          const res = await (window as any).electronAPI.savePlaylist(name, serializableTracks);
          try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Saved playlist ${name} via electron`); } catch (e) {}
          if (!res.ok) alert('Save failed: ' + res.error);
          else {
            // update local state to reflect saved playlist
            setPlaylists(prev => {
              const rest = prev.filter(p => p.name !== name);
              return [...rest, { name, tracks: serializableTracks }];
            });
            setSelectedPlaylistName(name);
            try { localStorage.setItem('defaultPlaylistName', name); } catch {}
            // no intrusive alert: show small confirmation
            setLogs(l=>[...l, `Saved playlist ${name}`]);
          }
        } catch (e) { console.warn('electron save failed', e); alert('Save failed: ' + String(e)); }
      } else {
        // fallback: save to localStorage
        try {
          const cur = JSON.parse(localStorage.getItem('playlists') || '[]');
          const rest = (Array.isArray(cur) ? cur.filter((p:any)=>p.name !== name) : []);
          const store = [...rest, { name, tracks: serializableTracks }];
          localStorage.setItem('playlists', JSON.stringify(store));
          setPlaylists(store);
          setSelectedPlaylistName(name);
          try { localStorage.setItem('defaultPlaylistName', name); } catch {}
          setLogs(l=>[...l, `Saved playlist ${name} locally`]);
        } catch (e) { alert('Save failed: ' + e); }
      }
    }

    function openRenameModal() {
      if (!selectedPlaylistName) { alert('No playlist selected to rename'); return; }
      setRenameValue(selectedPlaylistName);
      setRenameTarget(selectedPlaylistName);
      setRenameModalOpen(true);
    }

    async function confirmRename() {
      const oldName = renameTarget;
      const newName = (renameValue || '').trim();
      if (!oldName) { alert('No playlist selected to rename'); setRenameModalOpen(false); return; }
      if (!newName || newName === oldName) { setRenameModalOpen(false); return; }
      // avoid name collisions
      if (playlists.find(p => p.name === newName)) { alert('A playlist with that name already exists'); return; }

      const updated = playlists.map(p => p.name === oldName ? { ...p, name: newName } : p);
      setPlaylists(updated);
      setSelectedPlaylistName(newName);
      try { localStorage.setItem('playlists', JSON.stringify(updated)); } catch(e){}
      try { localStorage.setItem('defaultPlaylistName', newName); } catch(e){}

      // persist to disk if electron available
      try {
        const api = (window as any).electronAPI;
        if (api?.writePlaylists) {
          const res = await api.writePlaylists(updated);
          if (res?.ok) setLogs(l=>[...l, `Renamed playlist ${oldName} -> ${newName}`]);
          else setLogs(l=>[...l, `writePlaylists failed: ${res?.error}`]);
        } else if (api?.savePlaylist) {
          for (const p of updated) {
            await api.savePlaylist(p.name, p.tracks);
          }
          setLogs(l=>[...l, `Renamed (via per-save) ${oldName} -> ${newName}`]);
        }
      } catch (err) { setLogs(l=>[...l, `rename persist error: ${String(err)}`]); }

      setRenameModalOpen(false);
      setRenameTarget(null);
    }

    function cancelRename() {
      setRenameModalOpen(false);
      setRenameTarget(null);
    }

    async function deletePlaylist() {
      if (!selectedPlaylistName) { alert('No playlist selected to delete'); return; }
      const name = selectedPlaylistName;
      if (!confirm(`Delete playlist "${name}"? This cannot be undone.`)) return;
      const updated = playlists.filter(p => p.name !== name);
      setPlaylists(updated);
      setSelectedPlaylistName(null);
      setTracks([]);
      try { localStorage.setItem('playlists', JSON.stringify(updated)); } catch(e){}
      try { localStorage.removeItem('defaultPlaylistName'); } catch(e){}
      try {
        const api = (window as any).electronAPI;
        if (api?.writePlaylists) {
          const res = await api.writePlaylists(updated);
          if (res?.ok) setLogs(l=>[...l, `Deleted playlist ${name}`]);
          else setLogs(l=>[...l, `writePlaylists failed: ${res?.error}`]);
        } else if (api?.savePlaylist) {
          // delete by saving each remaining playlist (per-save fallback)
          for (const p of updated) {
            await api.savePlaylist(p.name, p.tracks);
          }
          setLogs(l=>[...l, `Deleted (via per-save) playlist ${name}`]);
        }
      } catch(err) { setLogs(l=>[...l, `delete persist error: ${String(err)}`]); }
    }

  // cleanup blob URLs on unmount
  useEffect(() => {
    return () => {
      for (const t of tracks) {
        if (t.src && t.src.startsWith('blob:')) URL.revokeObjectURL(t.src);
      }
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="app" role="application" aria-label="MintPlayer" style={{ background: 'radial-gradient(circle at top, #2b2931 0%, #17181d 28%, #0c0d10 100%)', color: '#f5f7fb', gap: 20, padding: '18px 18px 26px', height: '100vh', boxSizing: 'border-box' }}>
      <aside className={`playlists${isDragging ? ' drop-active' : ''}`} role="navigation" aria-label="Playlists" style={{ width: '20%', minWidth: 180, fontSize: '0.85rem', background: 'rgba(17,18,23,0.92)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 24, boxShadow: '0 18px 40px rgba(0,0,0,0.32)', color: '#eef2ff', padding: '18px 18px 8px', backdropFilter: 'blur(10px)', display: 'flex', flexDirection: 'column', flex: '0 0 24%', minHeight: 0, maxHeight: 'calc(100vh - 36px)' }} onDrop={handleDrop} onDragOver={onDragOver} onDragEnter={onDragEnter} onDragLeave={onDragLeave}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 10 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            <select value={selectedPlaylistName || ''} onChange={(e)=>{
                const v = e.target.value || null;
                console.log('playlist select changed', v);
                setLogs(l=>[...l, `Playlist select changed: ${v}`]);
                setSelectedPlaylistName(v);
                try { localStorage.setItem('defaultPlaylistName', v || ''); } catch {}
                if (v) {
                  const p = playlists.find(pl=>pl.name === v);
                  if (p) setTracks(p.tracks || []);
                }
              }} aria-label="Select playlist" style={{ background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.08)', color: '#f5f7fb', borderRadius: 10, padding: '8px 12px', minWidth: 110, flex: 1 }}>
                {playlists.map(pl => <option key={pl.name} value={pl.name} style={{ background: '#121418', color: '#f5f7fb' }}>{pl.name}</option>)}
              </select>
            <button className="icon-btn" style={{ marginLeft: 0, background: 'rgba(255,255,255,0.06)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }} onClick={openRenameModal} aria-label="Edit playlist" title="Edit playlist">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04a1.003 1.003 0 000-1.42l-2.34-2.34a1.003 1.003 0 00-1.42 0l-1.83 1.83 3.75 3.75 1.84-1.82z" fill="currentColor"/></svg>
            </button>
            <button className="icon-btn" style={{ marginLeft: 0, background: 'rgba(255,255,255,0.06)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }} onClick={deletePlaylist} aria-label="Delete playlist" title="Delete playlist">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M6 19a2 2 0 002 2h8a2 2 0 002-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z" fill="currentColor"/></svg>
            </button>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, flex: 1 }}>
              <input ref={addFilesInputRef} id="addFilesInput" type="file" multiple style={{ display: 'none' }} onChange={onFiles} />
              <input ref={addFolderInputRef} id="addFolderInput" type="file" {...({'webkitdirectory':'true'} as any)} style={{ display: 'none' }} onChange={onFolder as any} />

              <button className="icon-btn" onClick={()=> addFilesInputRef.current?.click()} aria-label="Add files" title="Add files" style={{ background: 'linear-gradient(135deg, #ff9c4b, #ff6b6b)', color: '#fff', border: 'none', boxShadow: '0 12px 28px rgba(255, 118, 66, 0.35)' }}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M19 13h-4v4H9v-4H5l7-7 7 7zM5 20h14v2H5z" fill="currentColor"/></svg>
              </button>
              <button className="icon-btn" style={{ marginLeft: 0, background: 'rgba(255,255,255,0.06)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }} onClick={()=>{ const win = (window as any).electronAPI; if (win?.chooseFolder) { (async ()=>{ await onFolder(undefined as any); })(); } else { addFolderInputRef.current?.click(); } }} aria-label="Add folder" title="Add folder">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M10 4H4a2 2 0 00-2 2v12a2 2 0 002 2h16a2 2 0 002-2V8a2 2 0 00-2-2h-8l-2-2zM12 12v4h-2v-4H8l4-4 4 4h-2z" fill="currentColor"/></svg>
              </button>
              <button className="icon-btn" style={{ marginLeft: 0, background: 'rgba(255,255,255,0.06)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }} onClick={savePlaylist} aria-label="Save playlist" title="Save playlist">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M17 3H5a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2V7l-4-4zM12 17a3 3 0 110-6 3 3 0 010 6zm5-9H7V5h10v3z" fill="currentColor"/></svg>
              </button>
            </div>

            <button className="icon-btn" style={{ marginLeft: 0, background: 'rgba(255,255,255,0.06)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }} onClick={() => setView(view === 'config' ? 'player' : 'config')} aria-label="Settings" title="Settings">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 8a4 4 0 100 8 4 4 0 000-8zm8.94 3a6.96 6.96 0 00-.11-1l2.03-1.57-2-3.46-2.39.96a6.9 6.9 0 00-1.3-.75l-.36-2.54H9.2l-.36 2.54c-.43.22-.85.48-1.24.77L4.15 7.43l-2 3.46 2.03 1.57c-.06.33-.06.67-.06 1s0 .67.06 1L2.15 16.9l2 3.46 2.39-.96c.39.29.81.55 1.24.77l.36 2.54h5.09l.36-2.54c.45-.22.9-.48 1.3-.75l2.39.96 2-3.46-2.03-1.57c.06-.33.11-.67.11-1z" fill="currentColor"/></svg>
            </button>
          </div>
        </div>
        {isDragging && <div className="drop-overlay">Drop files or folder here</div>}
        <div className="drop-zone" style={{ background: 'rgba(255,255,255,0.02)', borderRadius: 18, border: '1px solid rgba(255,255,255,0.04)', padding: 8, flex: '1 1 auto', minHeight: 0, display: 'flex', flexDirection: 'column' }}>
          {isDragging && <div className="drop-overlay">Drop files or folder here</div>}
          <ul role="listbox" aria-label="Tracks" className="track-list">
            {tracks.map((t, i) => (
              <li
                key={i}
                role="option"
                aria-selected={selected===i}
                tabIndex={0}
                onKeyDown={(e)=>{ if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setSelected(i); playIndex(i); } }}
                onClick={()=>{ setSelected(i); playIndex(i); }}
              >
                {t.name}{t.path ? ` — ${t.path}` : ''}
              </li>
            ))}
          </ul>
        </div>
      </aside>

      <main className="player" role="main" aria-label="Player" style={{ flex: '1 1 auto', minWidth: 0, display: 'flex', flexDirection: 'column', gap: 18, minHeight: 0, height: '100%' }}>
        {view === 'config' ? (
          <div style={{ background: 'rgba(18,18,23,0.92)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 24, padding: 24, boxShadow: '0 18px 40px rgba(0,0,0,0.32)' }}>
            <h2 style={{ marginTop: 0, color: '#f5f7fb' }}>Configuration</h2>
            <div style={{ marginBottom: 12 }}>
              <label style={{ display: 'block', marginBottom: 10, color: '#eef2ff' }}>
                <input type="checkbox" checked={showCover} onChange={(e)=>{ const v = e.target.checked; setShowCover(v); try{ localStorage.setItem('showCover', String(v)); }catch{} }} /> Show cover in player
              </label>
              <label style={{ display: 'block', marginBottom: 10, color: '#eef2ff' }}>
                <input type="checkbox" checked={autoGenerateBacking} onChange={(e)=>{ const v = e.target.checked; setAutoGenerateBacking(v); try{ localStorage.setItem('autoGenerateBacking', String(v)); }catch{} }} /> Auto-generate backing tracks when adding files/folders
              </label>
              <label style={{ display: 'block', marginBottom: 10, color: '#eef2ff' }}>
                <input type="checkbox" checked={autoNext} onChange={(e)=>{ const v = e.target.checked; setAutoNext(v); try{ localStorage.setItem('autoNext', String(v)); }catch{} }} /> Auto play next
              </label>
              <label style={{ display: 'block', marginBottom: 10, color: '#eef2ff' }}>
                <input type="checkbox" checked={loopPlaylist} onChange={(e)=>{ const v = e.target.checked; setLoopPlaylist(v); try{ localStorage.setItem('loopPlaylist', String(v)); }catch{} }} /> Loop playlist when finished
              </label>
            </div>
            <div>
              <button onClick={()=>setView('player')} style={{ borderRadius: 12, border: '1px solid rgba(255,255,255,0.12)', background: '#1d1f27', color: '#f5f7fb', padding: '10px 14px' }}>Back to Player</button>
            </div>
          </div>
        ) : (
          <>
            <div className="media-stage" style={{ display: 'flex', gap: 18, alignItems: 'stretch', flex: '1 1 auto', minHeight: 500, height: '100%', minWidth: 0 }}>
              <div style={{ position: 'relative', flex: 1, minWidth: 260, minHeight: 500, borderRadius: 24, boxShadow: '0 28px 60px rgba(0,0,0,0.32)', background: 'linear-gradient(135deg, #f6d38c 0%, #ff8f70 40%, #7a5cff 100%)', overflow: 'hidden' }}>
                <div style={{ position: 'absolute', left: 14, top: 14, zIndex: 20, display: 'flex', alignItems: 'center', gap: 12 }}>
                  <button
                    type="button"
                    onClick={() => setMediaFront((v) => v === 'lyrics' ? 'cover' : 'lyrics')}
                    style={{
                      padding: '10px 14px',
                      borderRadius: 12,
                      border: '1px solid rgba(255,255,255,0.12)',
                      background: 'rgba(255,255,255,0.04)',
                      color: '#f5f7fb',
                      fontWeight: 700,
                      cursor: 'pointer',
                      boxShadow: '0 12px 26px rgba(0,0,0,0.18)',
                      minWidth: 94,
                    }}
                  >
                    {mediaFront === 'lyrics' ? 'cover' : 'lyrics'}
                  </button>
                  <button
                    type="button"
                    onClick={() => setLyricsMode((v) => v === 'static' ? 'synchronized' : 'static')}
                    style={{
                      padding: '10px 14px',
                      borderRadius: 12,
                      border: '1px solid rgba(255,255,255,0.12)',
                      background: 'rgba(255,255,255,0.04)',
                      color: '#f5f7fb',
                      fontWeight: 700,
                      cursor: 'pointer',
                      boxShadow: '0 12px 26px rgba(0,0,0,0.18)',
                      minWidth: 110,
                    }}
                  >
                    {lyricsMode === 'static' ? 'static' : 'synchronized'}
                  </button>
                </div>
                {showCover && (
                  <div style={{ position: 'absolute', inset: 0, zIndex: mediaFront === 'cover' ? 2 : 1, opacity: 1, transition: 'opacity 0.18s ease' }}>
                    {current != null && tracks[current] && tracks[current].cover ? (
                      <img src={tracks[current].cover} alt="cover" style={{ width: '100%', height: '100%', objectFit: 'contain', display: 'block', background: 'rgba(13,15,20,0.18)' }} />
                    ) : (
                      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', width: '100%', height: '100%', color: '#fff', fontWeight: 700, letterSpacing: 0.4 }}>Cover</div>
                    )}
                  </div>
                )}
                <div style={{ position: 'absolute', inset: 0, zIndex: mediaFront === 'lyrics' ? 2 : 1, background: 'rgba(17,18,23,0.68)', borderRadius: 24, border: '1px solid rgba(255,255,255,0.06)', boxShadow: '0 18px 40px rgba(0,0,0,0.24)', padding: 18, opacity: mediaFront === 'lyrics' ? 1 : 0.82, transition: 'opacity 0.18s ease' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12, gap: 8 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }} />
                    <strong style={{ fontSize: '1rem', color: '#f5f7fb' }}>Lyrics</strong>
                  </div>
                  <div ref={lyricsContainerRef} style={{ maxHeight: 'calc(100% - 70px)', overflow: 'auto', background: 'rgba(255,255,255,0.02)', padding: 12, borderRadius: 16, border: '1px solid rgba(255,255,255,0.04)' }}>
                    {lyricsMode === 'static' ? (
                      <pre style={{ whiteSpace: 'pre-wrap', margin: 0, fontSize: '0.95rem', lineHeight: 1.7, color: '#edf3ff' }}>{(lyricsRaw) ? lyricsRaw : (lyricsTimed ? lyricsTimed.map(l=>l.text).join('\n') : 'No lyrics found')}</pre>
                    ) : (
                      <div>
                        {lyricsTimed && lyricsTimed.length ? (
                          lyricsTimed.map((l, i) => (
                            <div id={`lyr-line-${i}`} key={i} role="button" tabIndex={0} aria-label={`Seek to ${formatTime(l.time)}`} onClick={()=>seekAndPlay(l.time)} onKeyDown={(e)=>{ if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); seekAndPlay(l.time); } }} className="lyric-line" style={{ padding: '9px 10px', background: (i === lyricsIndex) ? 'linear-gradient(135deg, rgba(255,156,75,0.24), rgba(255,107,107,0.14))' : 'transparent', borderRadius: 10, transition: 'background 0.08s', fontWeight: (i === lyricsIndex) ? 800 : 400, color: (i===lyricsIndex)?'#fff':'#dfe6f4', cursor: 'pointer', marginBottom: 2 }}>
                              <span style={{ color: '#cdd9f8', marginRight: 10, fontFamily: 'monospace', fontSize: '0.78rem' }}>{`${Math.floor(l.time/60)}:${String(Math.floor(l.time%60)).padStart(2,'0')}`}</span>
                              <span style={{ fontSize: (i===lyricsIndex)? '1.05em' : '1em' }}>{l.text}</span>
                            </div>
                          ))
                        ) : (
                          <pre style={{ whiteSpace: 'pre-wrap', margin: 0, fontSize: '0.95rem', lineHeight: 1.7, color: '#edf3ff' }}>{lyricsRaw || 'No synchronized lyrics found'}</pre>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>

            <div className="player-bottom" style={{ display: 'flex', flexDirection: 'column', gap: 12, flex: '0 0 auto', minHeight: 0, minWidth: 0, width: '100%' }}>

              <div className="player-toolbar" style={{ display: 'flex', alignItems: 'center', gap: 12, width: '100%', minHeight: 52, flexWrap: 'wrap', background: 'rgba(17,18,23,0.9)', borderRadius: 22, border: '1px solid rgba(255,255,255,0.06)', padding: '12px 14px', boxShadow: '0 18px 40px rgba(0,0,0,0.25)', backdropFilter: 'blur(10px)' }}>
                <div className="seek" aria-label="Seek controls" style={{ display: 'flex', alignItems: 'center', gap: 8, flex: '1 1 260px', minWidth: 200 }}>
                  <span className="time" style={{ minWidth: 42, fontSize: '0.82rem', textAlign: 'center', color: '#dfe6f4' }}>{formatTime(seekTime)}</span>
                  <input type="range" min={0} max={Math.max(0, duration)} step={0.1} value={seekTime} onChange={(e)=>{ const v = Number(e.target.value); setSeekTime(v); try { if (shifterRef.current) { const dur = shifterRef.current.duration || duration || 0; const perc = dur ? Math.max(0, Math.min(1, v / dur)) : 0; try { shifterRef.current.percentagePlayed = perc; } catch(e){} } else if (audioRef.current) { try{ audioRef.current.currentTime = v; } catch(e){} } } catch(e) { console.warn('seek input change failed', e); } }} aria-label="Seek" style={{ flex: 1 }} />
                  <span className="time" style={{ minWidth: 42, fontSize: '0.82rem', textAlign: 'center', color: '#dfe6f4' }}>{formatTime(duration)}</span>
                </div>

                <div className="transport-actions" style={{ display: 'flex', alignItems: 'center', gap: 8, flex: '0 0 auto' }}>
                  <button className="icon-btn" onClick={prevTrack} aria-label="Previous" style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M11 18V6l-8.5 6L11 18zM22 6v12h-2V6h2z" fill="currentColor"/></svg>
                  </button>

                  <button className="icon-btn" onClick={async () => {
                    try {
                      if (shifterRef.current) {
                        if (!isPlaying) {
                          await (audioCtxRef.current?.state === 'suspended' ? audioCtxRef.current.resume() : Promise.resolve());
                          try { shifterRef.current.connect(pannerRef.current || gainRef.current); } catch (e) {}
                          setIsPlaying(true);
                        } else {
                          try { shifterRef.current.disconnect(); } catch (e) {}
                          setIsPlaying(false);
                        }
                      } else if (audioRef.current) {
                        if (audioRef.current.paused) {
                          await (audioCtxRef.current?.state === 'suspended' ? audioCtxRef.current.resume() : Promise.resolve());
                          await audioRef.current.play();
                          setIsPlaying(true);
                        } else {
                          audioRef.current.pause();
                          setIsPlaying(false);
                        }
                      }
                    } catch (e) {
                      console.warn('play toggle', e);
                    }
                  }} aria-label={isPlaying ? 'Pause' : 'Play'} style={{ background: 'linear-gradient(135deg, #ff9c4b, #ff6b6b)', color: '#fff', border: 'none', boxShadow: '0 16px 32px rgba(255,120,70,0.35)' }}>
                    {isPlaying ? (
                      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M6 5h4v14H6V5zm8 0h4v14h-4V5z" fill="currentColor"/></svg>
                    ) : (
                      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M8 5v14l11-7L8 5z" fill="currentColor"/></svg>
                    )}
                  </button>

                  <button className="icon-btn" onClick={nextTrack} aria-label="Next" style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M13 6v12l8.5-6L13 6zM2 18V6h2v12H2z" fill="currentColor"/></svg>
                  </button>
                </div>

                <div className="audio-controls" style={{ display: 'flex', alignItems: 'center', gap: 10, marginLeft: 0, flex: '1 1 220px', minWidth: 200, flexWrap: 'wrap' }}>
                  <button className="icon-btn" onClick={()=>{ if (volume > 0) { prevVolumeRef.current = volume; setVolume(0); } else { setVolume(prevVolumeRef.current || 1); } }} aria-label="Mute" style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>
                    {volume > 0 ? (
                      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5 9v6h4l5 4V5l-5 4H5z" fill="currentColor"/></svg>
                    ) : (
                      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M16.5 12l4.5 4.5L19.5 20 15 15.5 10.5 20 8.5 18 13 13.5 8.5 9 10.5 7 15 11.5 19.5 7 21 8.5 16.5 12z" fill="currentColor"/></svg>
                    )}
                  </button>
                  <input aria-label="Volume" type="range" min={0} max={1} step={0.01} value={volume} onChange={(e)=>{ const v = Number(e.target.value); setVolume(v); if (audioRef.current) try{ audioRef.current.volume = v; } catch(e){} }} style={{ width: 100 }} />
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: 8, flex: '0 0 auto', minWidth: 0, flexWrap: 'nowrap' }}>
                  <div className="pan-panel" style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 10px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 12, minWidth: 0, whiteSpace: 'nowrap' }}>
                    <label style={{ fontSize: '0.82rem', color: '#dfe6f4', fontWeight: 600 }}>Pan</label>
                    <input aria-label="Pan" type="range" min={-1} max={1} step={0.01} value={pan} onChange={(e)=>{ const v = Number(e.target.value); setPan(v); if (pannerRef.current) try{ pannerRef.current.pan.value = v; } catch(e){} }} style={{ width: 90, accentColor: '#ff9c4b' }} />
                  </div>

                  <div className="transpose-panel" style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 10px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 12, minWidth: 0, whiteSpace: 'nowrap' }}>
                    <button className="icon-btn" onClick={()=>setTranspose(-12)} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>-12</button>
                    <button className="icon-btn" onClick={()=>setTranspose(t=>Math.max(-12, t-1))} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>-1</button>
                    <div style={{ padding: '6px 10px', background: 'rgba(255,255,255,0.05)', borderRadius: 10, minWidth: 48, textAlign: 'center', fontWeight: 700, color: '#fff', border: '1px solid rgba(255,255,255,0.04)' }}>{transpose >= 0 ? '+'+transpose : transpose}</div>
                    <button className="icon-btn" onClick={()=>setTranspose(t=>Math.min(12, t+1))} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>+1</button>
                    <button className="icon-btn" onClick={()=>setTranspose(12)} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>+12</button>
                    <input type="range" min={-12} max={12} step={1} value={transpose} onChange={(e)=>setTranspose(Number(e.target.value))} aria-label="Transpose" style={{ width: 120, accentColor: '#ff9c4b' }} />
                  </div>
                </div>
              </div>
              <audio ref={audioRef} onError={(e)=>{ const a = e.currentTarget as HTMLAudioElement; console.error('audio error', a.error); setLogs(l=>[...l, 'audio error: ' + String(a.error?.message || a.error?.code || a.error || 'unknown')]); }} style={{ display: 'none', marginTop: 0, filter: 'sepia(0.2) saturate(1.2) brightness(1.05)' }} />

              <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                <button type="button" onClick={()=>setShowDebug((v)=>!v)} style={{ padding: '7px 12px', borderRadius: 10, border: '1px solid rgba(255,255,255,0.12)', background: 'rgba(255,255,255,0.04)', color: '#f5f7fb' }}>{showDebug ? 'Hide debug' : 'Show debug'}</button>
              </div>
              {showDebug && (
                <div style={{ background: 'rgba(17,18,23,0.9)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 20, padding: 16 }}>
                  <strong style={{ color: '#f5f7fb' }}>Debug:</strong>
                  <div style={{ display: 'flex', gap: 12, alignItems: 'flex-start', marginBottom: 8, marginTop: 8 }}>
                    <div style={{ flex: 1, maxHeight: 220, overflow: 'auto', background: '#0d0f15', padding: 8, borderRadius: 12, border: '1px solid rgba(255,255,255,0.08)' }}>
                      <pre style={{ whiteSpace: 'pre-wrap', color: '#dfe6f4', margin: 0 }}>{JSON.stringify(tracks.map(t=>({ id: t.id, name: t.name, hasFile: !!t.file, hasCover: !!t.cover, src: t.src })), null, 2)}</pre>
                    </div>
                    <div style={{ width: 240 }}>
                      <div style={{ marginBottom: 8 }}>
                        <label style={{ marginRight: 8, color: '#dfe6f4' }}>Transpose (semitones)</label>
                        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                          <button className="icon-btn" onClick={()=>setTranspose(-12)} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>-12</button>
                          <button className="icon-btn" onClick={()=>setTranspose(t=>Math.max(-12, t-1))} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>-1</button>
                          <div style={{ padding: '6px 10px', background: 'rgba(255,255,255,0.05)', borderRadius: 10, minWidth: 48, textAlign: 'center', color: '#fff' }}>{transpose >= 0 ? '+'+transpose : transpose}</div>
                          <button className="icon-btn" onClick={()=>setTranspose(t=>Math.min(12, t+1))} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>+1</button>
                          <button className="icon-btn" onClick={()=>setTranspose(12)} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>+12</button>
                        </div>
                        <input type="range" min={-12} max={12} step={1} value={transpose} onChange={(e)=>setTranspose(Number(e.target.value))} style={{ width: '100%', marginTop: 8 }} />
                      </div>
                      <div style={{ fontSize: 12, color: '#bfc9e6' }}>
                        Note: high-quality pitch-shifter will be integrated into the AudioWorklet processor. Current worklet is a skeleton; after integrating algorithm the transpose will change pitch while keeping tempo.
                      </div>
                    </div>
                  </div>
                  <div style={{ color: '#dfe6f4', whiteSpace: 'pre-wrap' }}>{logs.join('\n')}</div>
                </div>
              )}
            </div>
          </>
        )}
      </main>

      {renameModalOpen && (
        <div style={{ position: 'fixed', left: 0, top: 0, right: 0, bottom: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.5)', zIndex: 9999 }}>
          <div style={{ background: '#17181d', color: '#f5f7fb', padding: 16, borderRadius: 18, width: 340, boxShadow: '0 22px 50px rgba(0,0,0,0.36)', border: '1px solid rgba(255,255,255,0.05)' }}>
            <h3 style={{ marginTop: 0 }}>Rename playlist</h3>
            <input value={renameValue} onChange={(e)=>setRenameValue(e.target.value)} style={{ width: '100%', padding: 10, marginBottom: 12, borderRadius: 10, border: '1px solid rgba(255,255,255,0.08)', background: 'rgba(255,255,255,0.04)', color: '#f5f7fb' }} />
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
              <button onClick={cancelRename} style={{ borderRadius: 10, border: '1px solid rgba(255,255,255,0.1)', background: 'rgba(255,255,255,0.04)', color: '#f5f7fb', padding: '8px 12px' }}>Cancel</button>
              <button onClick={confirmRename} style={{ borderRadius: 10, border: 'none', background: 'linear-gradient(135deg, #ff9c4b, #ff6b6b)', color: '#fff', padding: '8px 12px' }}>OK</button>
            </div>
          </div>
        </div>
      )}

      {lyricsVisible && (
        <div style={{ position: 'fixed', left: 0, top: 0, right: 0, bottom: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.63)', zIndex: 10000 }}>
          <div style={{ background: '#17181d', color: '#f5f7fb', padding: 16, borderRadius: 20, width: '70%', maxWidth: 800, maxHeight: '80%', overflow: 'auto', boxShadow: '0 22px 50px rgba(0,0,0,0.32)', border: '1px solid rgba(255,255,255,0.08)' }}>
            <h3 style={{ marginTop: 0 }}>Lyrics</h3>
            <div style={{ marginBottom: 8 }}>
              <label style={{ marginRight: 8, color: '#dfe6f4' }}>Display mode:</label>
              <select value={lyricsMode} onChange={(e)=>setLyricsMode(e.target.value as any)} style={{ background: 'rgba(255,255,255,0.04)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 10, padding: '8px 10px' }}>
                <option value="static" style={{ background: '#17181d' }}>Static (no timestamps)</option>
                <option value="synchronized" style={{ background: '#17181d' }}>Synchronized (show timestamps if available)</option>
              </select>
            </div>
            <div ref={lyricsContainerRef} style={{ maxHeight: 400, overflow: 'auto', background: 'rgba(255,255,255,0.02)', padding: 12, borderRadius: 14, border: '1px solid rgba(255,255,255,0.04)' }}>
              {lyricsMode === 'static' ? (
                <pre style={{ whiteSpace: 'pre-wrap', margin: 0, fontSize: '0.95rem', lineHeight: 1.7, color: '#edf3ff' }}>{(lyricsRaw) ? lyricsRaw : (lyricsTimed ? lyricsTimed.map(l=>l.text).join('\n') : 'No lyrics found')}</pre>
              ) : (
                <div style={{ maxHeight: 360 }}>
                  {lyricsTimed && lyricsTimed.length ? (
                    lyricsTimed.map((l, i) => (
                    <div id={`lyr-line-${i}`} key={i} role="button" tabIndex={0} aria-label={`Seek to ${formatTime(l.time)}`} onClick={()=>seekAndPlay(l.time)} onKeyDown={(e)=>{ if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); seekAndPlay(l.time); } }} className="lyric-line" style={{ padding: '9px 10px', background: (i === lyricsIndex) ? 'linear-gradient(135deg, rgba(255,156,75,0.24), rgba(255,107,107,0.14))' : 'transparent', borderRadius: 10, transition: 'background 0.08s', fontWeight: (i === lyricsIndex) ? 800 : 400, color: (i===lyricsIndex)?'#fff':'#dfe6f4', cursor: 'pointer', marginBottom: 2 }}>
                        <span style={{ color: '#cdd9f8', marginRight: 10, fontFamily: 'monospace', fontSize: '0.78rem' }}>{`${Math.floor(l.time/60)}:${String(Math.floor(l.time%60)).padStart(2,'0')}`}</span>
                        <span style={{ fontSize: (i===lyricsIndex)? '1.05em' : '1em' }}>{l.text}</span>
                      </div>
                    ))
                  ) : (
                    <pre style={{ whiteSpace: 'pre-wrap', margin: 0, fontSize: '0.95rem', lineHeight: 1.7, color: '#edf3ff' }}>{lyricsRaw || 'No synchronized lyrics found'}</pre>
                  )}
                </div>
              )}
            </div>
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 8 }}>
              <button onClick={()=>{ setLyricsVisible(false); setLyricsRaw(null); setLyricsTimed(null); }} style={{ borderRadius: 10, border: '1px solid rgba(255,255,255,0.1)', background: 'rgba(255,255,255,0.04)', color: '#f5f7fb', padding: '8px 12px' }}>Close</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';

type Track = { id: string; name: string; path?: string; src?: string; file?: File; cover?: string; backingActive?: boolean; _originalSrc?: string };
type Playlist = { name: string; tracks: Track[] };

export default function App() {
  const [tracks, setTracks] = useState<Track[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [current, setCurrent] = useState<number | null>(null);
  const [selected, setSelected] = useState<number | null>(null);
  const [selectedPlaylistName, setSelectedPlaylistName] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const seekingRef = useRef<boolean>(false);
  const addFilesInputRef = useRef<HTMLInputElement | null>(null);
  const addFolderInputRef = useRef<HTMLInputElement | null>(null);
  const [logs, setLogs] = useState<string[]>([]);
  const playLockRef = useRef<boolean>(false);
  const [view, setView] = useState<'player'|'config'>('player');
  const [seekTime, setSeekTime] = useState<number>(0);
  const [duration, setDuration] = useState<number>(0);

  // sync audio progress and metadata (also reflect play/pause state)
  useEffect(() => {
    const a = audioRef.current;
    if (!a) return;
    const onTime = () => { if (!seekingRef.current) setSeekTime(a.currentTime || 0); };
    const onMeta = () => setDuration(a.duration || 0);
    const onPlay = () => setIsPlaying(true);
    const onPause = () => setIsPlaying(false);
    a.addEventListener('timeupdate', onTime);
    a.addEventListener('loadedmetadata', onMeta);
    a.addEventListener('durationchange', onMeta);
    a.addEventListener('play', onPlay);
    a.addEventListener('pause', onPause);
    return () => {
      try { a.removeEventListener('timeupdate', onTime); } catch(e){}
      try { a.removeEventListener('loadedmetadata', onMeta); } catch(e){}
      try { a.removeEventListener('durationchange', onMeta); } catch(e){}
      try { a.removeEventListener('play', onPlay); } catch(e){}
      try { a.removeEventListener('pause', onPause); } catch(e){}
    };
  }, [audioRef]);

  // playback + audio routing states
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState<number>(0.5);
  const [pan, setPan] = useState<number>(0);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<any>(null);
  const gainRef = useRef<any>(null);
  const pannerRef = useRef<any>(null);
  const workletRef = useRef<any>(null);
  const shifterRef = useRef<any>(null);
  const shifterPollRef = useRef<number | null>(null);
  const prevVolumeRef = useRef<number>(0.5);
  const [transpose, setTranspose] = useState<number>(0); // semitones (-12..12)

  // backing track preferences/state
  const [autoGenerateBacking, setAutoGenerateBacking] = useState<boolean>(false);
  const [backingAvailableMap, setBackingAvailableMap] = useState<Record<string, boolean>>({});
  // guards for async readFile requests to avoid stale callbacks applying blobs
  const readRequestIdRef = useRef<Record<string, number>>({});
    // track id currently requested for playback (synchronous guard across async callbacks)
    const currentTrackIdRef = useRef<string | null>(null);


  // create audio graph when audio element is available
  useEffect(() => {
    const a = audioRef.current;
    if (!a) return;
    if (audioCtxRef.current) return; // already created
    try {
      const C = (window as any).AudioContext || (window as any).webkitAudioContext;
      if (!C) return;
        const ctx = new C();
      audioCtxRef.current = ctx;
      const src = ctx.createMediaElementSource(a);
      const gain = ctx.createGain();
      let panner: any = null;
      try { panner = ctx.createStereoPanner ? ctx.createStereoPanner() : null; } catch(e) { panner = null; }
      sourceRef.current = src;
      gainRef.current = gain;
      pannerRef.current = panner;

      // attempt to load the pitch-shifter AudioWorklet processor (skeleton)
      try {
        // Vite serves files under the module graph; use import.meta.url to resolve relative path
        const moduleURL = new URL('./pitch-shifter-processor.js', import.meta.url);
        // Load worklet module asynchronously in an IIFE to avoid making the effect callback async
        (async () => {
          try {
            await ctx.audioWorklet.addModule(moduleURL.href);
            const workletNode = new AudioWorkletNode(ctx, 'pitch-shifter-processor', { numberOfInputs: 1, numberOfOutputs: 1, outputChannelCount: [2] });
            workletRef.current = workletNode;
            // connect graph: media element -> worklet -> panner? -> gain -> destination
            if (panner) {
              src.connect(workletNode);
              workletNode.connect(panner);
              panner.connect(gain);
            } else {
              src.connect(workletNode);
              workletNode.connect(gain);
            }
          } catch (e) {
            console.warn('AudioWorklet module load failed, falling back to direct connect', e);
            if (panner) { src.connect(panner); panner.connect(gain); } else { src.connect(gain); }
          }
        })();
      } catch (e) {
        // fallback: connect directly when worklet not available
        console.warn('AudioWorklet not available or failed to load, falling back to direct connect', e);
        if (panner) { src.connect(panner); panner.connect(gain); } else { src.connect(gain); }
      }

      gain.connect(ctx.destination);
      gain.gain.value = volume;
      if (panner && typeof panner.pan !== 'undefined') panner.pan.value = pan;
    } catch (e) { console.warn('audio graph setup failed', e); }
  }, [audioRef]);

  // reflect volume and pan changes into graph and element
  useEffect(() => {
    if (audioRef.current) try{ audioRef.current.volume = volume; } catch(e){}
    if (gainRef.current) try{ gainRef.current.gain.value = volume; } catch(e){}
  }, [volume]);
  useEffect(() => {
    if (pannerRef.current && typeof pannerRef.current.pan !== 'undefined') try{ pannerRef.current.pan.value = pan; } catch(e){}
  }, [pan]);

  // reflect transpose changes into worklet (skeleton)
  useEffect(() => {
    try {
      if (workletRef.current && workletRef.current.port) {
        workletRef.current.port.postMessage({ type: 'setSemitones', value: transpose });
      }
      // If using the SoundTouch PitchShifter, update its semitones as well
      if (shifterRef.current) {
        try { shifterRef.current.pitchSemitones = transpose; } catch(e) { /* ignore */ }
      }
      // Note: the current processor is a pass-through skeleton. Replace processor with a
      // real pitch-shifting implementation (SoundTouch or similar) to get audible transpose
      // without affecting tempo when using the worklet implementation.
    } catch (e) { console.warn('transpose update failed', e); }
  }, [transpose]);

  function formatTime(t: number) {
    if (!t || isNaN(t)) return '0:00';
    const m = Math.floor(t / 60);
    const s = Math.floor(t % 60);
    return `${m}:${String(s).padStart(2,'0')}`;
  }

  function seekAndPlay(time: number) {
    try {
      if (shifterRef.current) {
        try {
          const dur = shifterRef.current.duration || duration || 0;
          const perc = dur ? Math.max(0, Math.min(1, Number(time) / dur)) : 0;
          shifterRef.current.percentagePlayed = perc;
          // resume if paused
          if (!isPlaying) {
            try { shifterRef.current.connect(pannerRef.current || gainRef.current); } catch(e){}
            setIsPlaying(true);
          }
          setSeekTime(time);
          return;
        } catch (e) { console.warn('shifter seek failed', e); }
      }

      if (!audioRef.current) return;
      // set currentTime then play; some browsers require play() after setting time
      audioRef.current.currentTime = Math.max(0, Number(time) || 0);
      const p = audioRef.current.play();
      if (p && typeof (p as any).then === 'function') {
        (p as any).then(() => setIsPlaying(true)).catch(()=>{});
      } else {
        setIsPlaying(true);
      }
      setSeekTime(time);
    } catch (e) { console.warn('seekAndPlay', e); }
  }
  const [showCover, setShowCover] = useState<boolean>(true);
  const [mediaFront, setMediaFront] = useState<'lyrics'|'cover'>('lyrics');
  const [lyricsRaw, setLyricsRaw] = useState<string | null>(null);
  const [lyricsTimed, setLyricsTimed] = useState<Array<{time:number;text:string}>|null>(null);
  const [lyricsVisible, setLyricsVisible] = useState<boolean>(false);
  const [lyricsMode, setLyricsMode] = useState<'static'|'synchronized'>('synchronized');
  const [lyricsIndex, setLyricsIndex] = useState<number>(0);
  const lyricsContainerRef = useRef<HTMLDivElement|null>(null);
  const [showDebug, setShowDebug] = useState<boolean>(false);

  // Lyrics timeupdate handler management
  const lyricsTimeHandlerRef = useRef<((e?: any)=>void)|null>(null);
  function attachLyricsTimeListener() {
    detachLyricsTimeListener();
    if (!lyricsTimed || lyricsTimed.length === 0) return;

    // If using PitchShifter, poll its timePlayed because it doesn't update the <audio> element
    if (shifterRef.current) {
      try {
        shifterPollRef.current = window.setInterval(() => {
          try {
            const sh = shifterRef.current;
            if (!sh) return;
            const t = (typeof sh.timePlayed === 'number') ? sh.timePlayed : (sh.sourcePosition && sh.sampleRate ? (sh.sourcePosition / sh.sampleRate) : 0);
            if (!seekingRef.current) setSeekTime(t);
            let idx = lyricsTimed.findIndex((l, i) => {
              const next = lyricsTimed[i+1];
              return t >= l.time && (!next || t < next.time);
            });
            if (idx === -1) {
              if (t < (lyricsTimed[0]?.time||0)) idx = 0; else idx = lyricsTimed.length -1;
            }
            setLyricsIndex(idx);
          } catch (e) { /* ignore */ }
        }, 200);
      } catch (e) { console.warn('shifter poll failed', e); }
      return;
    }

    const audio = audioRef.current;
    if (!audio) return;
    const handler = () => {
      try {
        const t = audio.currentTime;
        if (!seekingRef.current) setSeekTime(t);
        let idx = lyricsTimed.findIndex((l, i) => {
          const next = lyricsTimed[i+1];
          return t >= l.time && (!next || t < next.time);
        });
        if (idx === -1) {
          if (t < (lyricsTimed[0]?.time||0)) idx = 0; else idx = lyricsTimed.length -1;
        }
        setLyricsIndex(idx);
      } catch (e) { /* ignore */ }
    };
    lyricsTimeHandlerRef.current = handler;
    audio.addEventListener('timeupdate', handler);
  }
  function detachLyricsTimeListener() {
    // clear shifter poll if present
    if (shifterPollRef.current) {
      try { clearInterval(shifterPollRef.current); } catch(e){}
      shifterPollRef.current = null;
    }
    const audio = audioRef.current;
    const h = lyricsTimeHandlerRef.current;
    if (audio && h) audio.removeEventListener('timeupdate', h);
    lyricsTimeHandlerRef.current = null;
  }
  useEffect(() => {
    if (lyricsTimed && lyricsTimed.length) attachLyricsTimeListener(); else detachLyricsTimeListener();
    return () => detachLyricsTimeListener();
  }, [lyricsTimed]);

  useEffect(() => {
    // keep active line centered in the lyrics panel after the first few lines
    try {
      const container = lyricsContainerRef.current;
      const el = container ? container.querySelector(`#lyr-line-${lyricsIndex}`) : document.getElementById(`lyr-line-${lyricsIndex}`);
      if (!el || !container) return;
      const elEl = el as HTMLElement;

      // compute using bounding rects so offsets work even with nested elements
      const containerRect = container.getBoundingClientRect();
      const elRect = elEl.getBoundingClientRect();
      const distanceFromTop = elRect.top - containerRect.top;
      const desiredScrollTop = Math.max(0, container.scrollTop + distanceFromTop - (container.clientHeight / 2) + (elEl.clientHeight / 2));
      const maxScroll = Math.max(0, container.scrollHeight - container.clientHeight);
      const target = Math.min(maxScroll, desiredScrollTop);

      if (lyricsIndex > 2) {
        container.scrollTo({ top: target, behavior: 'smooth' });
      } else {
        // ensure visible for first few lines
        const elBottom = container.scrollTop + distanceFromTop + elEl.offsetHeight;
        const viewTop = container.scrollTop;
        const viewBottom = viewTop + container.clientHeight;
        if (distanceFromTop < 0 || elBottom > viewBottom) {
          container.scrollTo({ top: Math.max(0, container.scrollTop + distanceFromTop - 8), behavior: 'smooth' });
        }
      }
    } catch (e) { console.warn('lyrics scroll error', e); }
  }, [lyricsIndex]);

  // rename modal state
  const [renameModalOpen, setRenameModalOpen] = useState(false);
  const [renameValue, setRenameValue] = useState('');
  const [renameTarget, setRenameTarget] = useState<string | null>(null);
  const [autoNext, setAutoNext] = useState<boolean>(false);
  const [loopPlaylist, setLoopPlaylist] = useState<boolean>(false);
  const [isDragging, setIsDragging] = useState<boolean>(false);
  const dragCounter = useRef<number>(0);

  // load saved playlists once on mount (do not re-run on tracks change)
  useEffect(() => {
    const load = async () => {
      try {
        if ((window as any).electronAPI?.loadPlaylists) {
          const res = await (window as any).electronAPI.loadPlaylists();
          if (res && res.ok && Array.isArray(res.playlists)) {
            // Normalize saved playlists: convert tracks with file:// src into path entries, and strip any non-serializable fields
            const normalized = res.playlists.map((pl: any) => {
              const tracks = (pl.tracks || []).map((t: any) => {
                const tt: any = { id: t.id, name: t.name, path: t.path, src: t.src, cover: t.cover };
                // if src is a file:// URL, music:// URL and path missing, derive path
                if (!tt.path && tt.src && typeof tt.src === 'string') {
                  if (tt.src.startsWith('file://')) {
                    try { tt.path = decodeURI(tt.src.replace(/^file:\/\//, '')); } catch (e) { tt.path = tt.src.replace(/^file:\/\//, ''); }
                  } else if (tt.src.startsWith('music://')) {
                    try {
                      const u = new URL(tt.src);
                      let pth = decodeURIComponent(u.pathname || '');
                      // strip leading slashes that may precede Windows drives
                      if (pth.startsWith('/')) pth = pth.replace(/^\/+/, '');
                      tt.path = pth;
                    } catch (e) {
                      try { tt.path = decodeURIComponent(tt.src.replace(/^music:\/\//, '')); } catch (e2) { tt.path = tt.src.replace(/^music:\/\//, ''); }
                    }
                  }
                }
                return tt;
              });
              return { name: pl.name, tracks };
            });

            setPlaylists(normalized);
            const def = localStorage.getItem('defaultPlaylistName');
            const p = def ? normalized.find((pl: any) => pl.name === def) : (normalized[0] || null);
            if (p) {
              setSelectedPlaylistName(p.name);
              setTracks(p.tracks || []);
            }

            // recreate blob URLs for tracks that have a path (Electron environment)
            try {
              const api = (window as any).electronAPI;
              if (api?.readFile) {
                for (const pl of normalized) {
                  for (let idx = 0; idx < (pl.tracks || []).length; idx++) {
                    const t = pl.tracks[idx];
                    if (t && t.path) {
                      (async (track) => {
                        try {
                          const rf = await api.readFile(track.path);
                          if (rf && rf.ok && rf.data) {
                            const binary = atob(rf.data);
                            const len = binary.length;
                            const u8 = new Uint8Array(len);
                            for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
                            const blob = new Blob([u8], { type: rf.mime || 'application/octet-stream' });
                            const url = URL.createObjectURL(blob);
                            // update playlists state and tracks state if this playlist is selected
                            setPlaylists(prev => prev.map((pls:any) => ({ ...pls, tracks: (pls.tracks || []).map((pt:any) => pt.path === track.path ? { ...pt, src: url } : pt) })));
                            setTracks(cur => cur.map(pt => pt.path === track.path ? { ...pt, src: url } : pt));
                            setLogs(l=>[...l, `Recreated blob for saved track ${track.name}`]);

                                                // Try extracting cover art from the recreated blob and apply to state
                                                try {
                                                  const fileObj = (typeof File !== 'undefined') ? new File([blob], track.name, { type: rf.mime || 'application/octet-stream' }) : undefined;
                                                  const extractTarget: File | Blob = fileObj || blob;
                                                  const coverUrl = await extractCoverFromFile(extractTarget as any);
                                                  if (coverUrl) {
                                                    setPlaylists(prev => prev.map((pls:any) => ({ ...pls, tracks: (pls.tracks || []).map((pt:any) => pt.path === track.path ? { ...pt, cover: coverUrl } : pt) })));
                                                    setTracks(cur => cur.map(pt => pt.path === track.path ? { ...pt, cover: coverUrl } : pt));
                                                    setLogs(l=>[...l, `Extracted cover for saved track ${track.name}`]);
                                                  } else {
                                                    setLogs(l=>[...l, `No cover found in saved track ${track.name}`]);
                                                  }
                                                } catch (covErr) {
                                                  setLogs(l=>[...l, `cover extract failed for saved track ${track.name}: ${String(covErr)}`]);
                                                }

                                              } else {
                                                setLogs(l=>[...l, `readFile failed for saved track ${track?.name}: ${rf?.error || 'unknown'}`]);
                                              }
                                            } catch (err) { setLogs(l=>[...l, `readFile exception for saved track ${track?.name}: ${String(err)}`]); }
                                          })(t);
                                        }
                  }
                }
              }
            } catch (e) { setLogs(l=>[...l, `recreate on load error: ${String(e)}`]); }

            return;
          }
        }
      } catch (e) { console.warn('loadPlaylists electron failed', e); }
      // fallback to localStorage
      try {
        const raw = localStorage.getItem('playlists');
        if (raw) {
          const arr = JSON.parse(raw || '[]');
          if (Array.isArray(arr)) {
            setPlaylists(arr);
            const def = localStorage.getItem('defaultPlaylistName');
            const p = def ? arr.find((pl: any) => pl.name === def) : (arr[0] || null);
            if (p) { setSelectedPlaylistName(p.name); setTracks(p.tracks || []); }
          }
        }
      } catch (e) { /* ignore */ }
    };
    load();
  }, []);

  // when playlists change and no selection, default to first playlist
  useEffect(() => {
    if ((!selectedPlaylistName || selectedPlaylistName === '') && playlists && playlists.length > 0) {
      const p = playlists[0];
      setSelectedPlaylistName(p.name);
      setTracks(p.tracks || []);
    }
  }, [playlists]);

  // keyboard delete handler
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Delete' && selected != null) {
        const t = tracks[selected];
        if (t && t.src && t.src.startsWith('blob:')) URL.revokeObjectURL(t.src);
        setTracks(prev => prev.filter((_, i) => i !== selected));
        setSelected(null);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [selected, tracks]);

  // load preferences from localStorage
  useEffect(() => {
    try {
      const sv = localStorage.getItem('showCover');
      setShowCover(sv === null ? true : sv === 'true');
      const an = localStorage.getItem('autoNext');
      setAutoNext(an === 'true');
      const lp = localStorage.getItem('loopPlaylist');
      setLoopPlaylist(lp === 'true');
      const ab = localStorage.getItem('autoGenerateBacking');
      setAutoGenerateBacking(ab === 'true');
    } catch (e) { /* ignore */ }
  }, []);

  // show B button only when selected track has an existing backing file
  useEffect(() => {
    const check = async () => {
      const activeIndex = current ?? selected;
      if (activeIndex == null) return;
      const t = tracks[activeIndex];
      if (!t || !t.path) return;
      const pth = t.path.replace(/\\/g,'/');
      const dir = pth.replace(/\/[^/]*$/, '');
      const base = (pth.split('/').pop() || '').replace(/\.[^/.]+$/, '');
      const candMp3 = dir + '/' + base + '_backingtrack.mp3';
      const candWav = dir + '/' + base + '_backingtrack.wav';
      try {
        const api = (window as any).electronAPI;
        if (!api?.stat) return;
        const s1 = await api.stat(candMp3);
        if (s1 && s1.ok && s1.isFile) { setBackingAvailableMap(m => ({ ...m, [t.id]: true })); return; }
        const s2 = await api.stat(candWav);
        if (s2 && s2.ok && s2.isFile) { setBackingAvailableMap(m => ({ ...m, [t.id]: true })); return; }
        setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
      } catch (e) {
        setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
      }
    };
    check();
  }, [current, selected, tracks]);

  async function extractCoverFromFile(file: File | Blob): Promise<string | null> {
    try { setLogs(l=>[...l, `extractCoverFromFile start for ${(file as any).name || 'blob'}`]); } catch(e){}
    try {
      // ensure Buffer polyfill for browser builds
      if (typeof (window as any).Buffer === 'undefined') {
        try {
          const bufmod = await import('buffer');
          (window as any).Buffer = bufmod.Buffer;
          setLogs(l=>[...l, 'polyfilled Buffer']);
        } catch (bufErr) {
          console.warn('buffer polyfill failed', bufErr);
          setLogs(l=>[...l, 'buffer polyfill failed: ' + String(bufErr)]);
        }
      }
      const mm = await import('music-metadata-browser');
      const metadata = await (mm as any).parseBlob(file);
      // detailed logging for diagnosis
      try { setLogs(l=>[...l, `metadata common keys: ${Object.keys(metadata.common || {}).join(',')}; pictures:${(metadata.common?.picture?.length)||0}`]); } catch(e){}
      console.log('music-metadata metadata', metadata);
      const pics = metadata?.common?.picture;
      if (pics && pics.length > 0) {
        const pic = pics[0];
        const blob = new Blob([pic.data as any], { type: pic.format || 'image/jpeg' });
        return URL.createObjectURL(blob);
      }
    } catch (e) {
      console.warn('music-metadata-browser parse failed', e);
      try { setLogs(l=>[...l, 'parse failed: ' + String(e)]); } catch(e){}
    }
    return null;
  }

  function parseTimestampedLyrics(text: string): Array<{time:number;text:string}> {
    const out: Array<{time:number;text:string}> = [];
    if (!text) return out;
    const lines = text.split(/\r?\n/);
    const timeRe = /\[?(\d{1,2}):(\d{2})(?:[.:](\d{1,3}))?\]?\s*(.*)/;
    for (const line of lines) {
      const m = line.match(timeRe);
      if (m) {
        const mins = parseInt(m[1], 10);
        const secs = parseInt(m[2], 10);
        const ms = m[3] ? parseInt((m[3] + '00').slice(0,3), 10) : 0;
        const time = mins * 60 + secs + ms / 1000;
        const textPart = m[4] || '';
        out.push({ time, text: textPart });
      }
    }
    // sort by time
    out.sort((a,b)=>a.time-b.time);
    return out;
  }

  async function getLyricsForTrack(t: Track): Promise<boolean> {
    try {
      const api = (window as any).electronAPI;
      setLyricsRaw(null);
      setLyricsTimed(null);
      // Ask main process (preferred for files on disk)
      if (t.path && api?.getLyrics) {
        try {
          const res = await api.getLyrics(t.path);
          if (res && res.ok) {
            setLyricsRaw(res.lyrics || null);
            if (res.timed && Array.isArray(res.timed) && res.timed.length) {
              setLyricsTimed(res.timed.map((it:any)=>({ time: Number(it.time)||0, text: String(it.text||'') })));
              return true;
            } else {
              // attempt to parse timestamped lines from returned lyrics text
              if (res.lyrics && typeof res.lyrics === 'string') {
                const parsed = parseTimestampedLyrics(res.lyrics);
                if (parsed.length) { setLyricsTimed(parsed); return true; }
              }
              setLyricsTimed(null);
              return false;
            }
          }
        } catch (e) { /* ignore */ }
      }

      // try reading from File/blob using music-metadata-browser
      try {
        if (t.file) {
          const mm = await import('music-metadata-browser');
          const meta = await (mm as any).parseBlob(t.file);
          const lyr = meta?.common?.lyrics;
          if (lyr && lyr.length) { setLyricsRaw(lyr.join('\n')); setLyricsTimed(null); // attempt parse
            const parsed = parseTimestampedLyrics(lyr.join('\n'));
            if (parsed.length) { setLyricsTimed(parsed); return true; }
            return false; }
        }
      } catch (e) { /* ignore */ }

      // fallback: if path available, read file via electron readFile and parse blob (client-side parse)
      try {
        if (t.path && api?.readFile) {
          const rf = await api.readFile(t.path);
          if (rf && rf.ok && rf.data) {
            const binary = atob(rf.data);
            const len = binary.length;
            const u8 = new Uint8Array(len);
            for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
            const blob = new Blob([u8], { type: rf.mime || 'application/octet-stream' });
            const mm = await import('music-metadata-browser');
            const meta = await (mm as any).parseBlob(blob);
            const lyr = meta?.common?.lyrics;
            if (lyr && lyr.length) { setLyricsRaw(lyr.join('\n')); setLyricsTimed(null); const parsed = parseTimestampedLyrics(lyr.join('\n'));
            if (parsed.length) { setLyricsTimed(parsed); return true; } return false; }
          }
        }
      } catch (e) { /* ignore */ }

      // nothing found
      setLyricsRaw(null);
      setLyricsTimed(null);
      return false;
    } catch (e) { setLyricsRaw(null); setLyricsTimed(null); return false; }
  }

  async function generateBackingForTracks(list: Track[]) {
    const api = (window as any).electronAPI;
      const results: { id: string; name: string; ok: boolean; path?: string; error?: string }[] = [];
      setLogs(l => [...l, `generateBackingForTracks: called for ${list.length} tracks`]);
      try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`generateBackingForTracks called for ${list.length} tracks`); } catch(e){}
      if (!api?.generateBacking) {
        setLogs(l => [...l, 'generateBacking API not available on window.electronAPI']);
        try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog('generateBacking API not available on window.electronAPI'); } catch(e){}
        // mark as unavailable
        for (const t of list) setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
        return;
      }
    const tasks: Promise<void>[] = [];
    for (const t of list) {
        const task = (async () => {
          try {
            let targetPath: string | undefined = undefined;
            if (t.path) targetPath = t.path;
            else if (t.file && api?.writeTempFile) {
              try {
                const arrBuf = await (t.file as File).arrayBuffer();
                const u8 = new Uint8Array(arrBuf);
                let binary = '';
                for (let i = 0; i < u8.length; i++) binary += String.fromCharCode(u8[i]);
                const b64 = btoa(binary);
                const wt = await api.writeTempFile(t.name, b64);
                if (wt && wt.ok && wt.path) targetPath = wt.path;
                else {
                  results.push({ id: t.id, name: t.name, ok: false, error: wt?.error || 'write temp failed' });
                  setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
                  return;
                }
              } catch (we) {
                results.push({ id: t.id, name: t.name, ok: false, error: String(we) });
                setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
                return;
              }
            } else {
              // no path and no file -> cannot generate
              results.push({ id: t.id, name: t.name, ok: false, error: 'no source path' });
              setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
              return;
            }

            if (!targetPath) {
              results.push({ id: t.id, name: t.name, ok: false, error: 'no target path' });
              setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
              return;
            }

            setLogs(l => [...l, `generateBacking: invoking for ${t.name} -> ${targetPath}`]);
            try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`generateBacking: invoking for ${t.name} -> ${targetPath}`); } catch(e){}
            const res = await api.generateBacking(targetPath);
            if (res && res.ok && res.path) {
              results.push({ id: t.id, name: t.name, ok: true, path: res.path });
              setBackingAvailableMap(m => ({ ...m, [t.id]: true }));
              setLogs(l => [...l, `generateBacking succeeded for ${t.name}: ${res.path}`]);
              try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`generateBacking succeeded for ${t.name}: ${res.path}`); } catch(e){}
            } else {
              results.push({ id: t.id, name: t.name, ok: false, error: res?.error || 'no output' });
              setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
              setLogs(l => [...l, `generateBacking failed for ${t.name}: ${res?.error || 'no output'}`]);
              try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`generateBacking failed for ${t.name}: ${res?.error || 'no output'}`); } catch(e){}
            }
          } catch (e: any) {
            results.push({ id: t.id, name: t.name, ok: false, error: String(e) });
            setBackingAvailableMap(m => ({ ...m, [t.id]: false }));
          }
        })();
        tasks.push(task);
      }
      if (tasks.length === 0) return;
      await Promise.all(tasks);
      const okCount = results.filter(r => r.ok).length;
      const failCount = results.length - okCount;
      setLogs(l => [...l, `Auto-generate backing finished: ${okCount} succeeded, ${failCount} failed`]);
      try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Auto-generate backing finished: ${okCount} succeeded, ${failCount} failed`); } catch(e){}
      if (okCount > 0) alert(`Backing track ready: ${okCount} succeeded${failCount>0?`, ${failCount} failed`:''}`);
      else alert(`No backing tracks produced (${failCount} attempts failed)`);
    }

  function addFilesFromFileList(fileList: FileList) {
    const arr: Track[] = [];
    for (let i = 0; i < fileList.length; i++) {
      const f = fileList.item(i)! as any;
      const name = f.name;
      const p = (f as any).path || undefined;
          // Skip backing tracks if user doesn't want them mixed into playlists
          if (name.match(/_backingtrack\.(mp3|wav)$/i)) continue;
          if (!name.match(/\.(mp3|flac)$/i)) continue;
          // Prefer using blob URLs for playback (works in browser and Electron) even if a file.path exists.
          const src = URL.createObjectURL(f);
          const id = p ? `path:${p}` : `${name}:${f.size}:${f.lastModified}`;
          const track: Track = { id, name, src, file: f };
          if (p) track.path = p;
          arr.push(track);
        }

    setTracks(prev => {
      const newTracks = [...prev, ...arr];
      setLogs(l=>[...l, `Added ${arr.length} files from file input`]);
      try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Added ${arr.length} files from file input`); } catch (e) {}

      // If running in Electron, and we have file paths, read from disk to create stable blob URLs
      const api = (window as any).electronAPI;
      if (api?.readFile) {
        for (const t of arr) {
          if (t.path) {
            (async () => {
              try {
                const res = await api.readFile(t.path);
                if (res && res.ok && res.data) {
                  const binary = atob(res.data);
                  const len = binary.length;
                  const u8 = new Uint8Array(len);
                  for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
                  const blob = new Blob([u8], { type: res.mime || 'application/octet-stream' });
                  const url = URL.createObjectURL(blob);
                            // Update track src; if this track is currently playing, swap src on the audio element while preserving time/play state
                            setTracks(currentTracks => {
                              const updated = currentTracks.map(ct => ct.id === t.id ? { ...ct, src: url } : ct);
                              try {
                                const curIdx = current;
                                if (curIdx != null) {
                                  const curTrack = currentTracks[curIdx];
                                  if (curTrack && curTrack.id === t.id && audioRef.current) {
                                    const wasPlaying = !audioRef.current.paused;
                                    const curTime = audioRef.current.currentTime || 0;
                                    try { audioRef.current.src = url; } catch(e) { /* ignore */ }
                                    try { audioRef.current.currentTime = Math.max(0, Math.min(curTime, audioRef.current.duration || curTime)); } catch(e) { }
                                    if (wasPlaying) {
                                      try { const p = audioRef.current.play(); if (p && typeof (p as any).then === 'function') p.catch(()=>{}); } catch(e) {}
                                    }
                                  }
                                }
                              } catch(e) {
                                console.warn('preserve audio src swap failed', e);
                              }
                              return updated;
                            });
                            setLogs(l=>[...l, `readFile created blob for ${t.name}`]);
                          } else {
                            setLogs(l=>[...l, `readFile failed for ${t.name}: ${res?.error || 'unknown'}`]);
                          }
                        } catch (err) {
                          setLogs(l=>[...l, `readFile exception ${String(err)}`]);
                        }
                      })();
                    }
        }
      }

      // attempt to extract cover art for newly added files (browser blobs)
      for (const t of newTracks) {
        if (t.file && !t.cover) {
          // kick off extraction but do not await here
          extractCoverFromFile(t.file).then(url => {
            if (url) {
              setLogs(l => [...l, `extracted cover for ${t.name}`]);
              setTracks(currentTracks => currentTracks.map(ct => ct.id === t.id ? { ...ct, cover: url } : ct));
            } else {
              setLogs(l => [...l, `no cover in ${t.name}`]);
            }
          }).catch(err => {
            console.warn('extract cover failed', err);
            setLogs(l => [...l, `cover extract error ${t.name}: ${String(err)}`]);
          });
        }
      }

      return newTracks;
    });

    // kick off auto-generate if enabled
    if (autoGenerateBacking) {
      generateBackingForTracks(arr);
    }
  }


    async function addFilesFromPathList(paths: string[]) {
      const arr: Track[] = [];
      const api = (window as any).electronAPI;
      for (const p of paths) {
        const name = p.split(/[/\\]/).pop() || p;
              // Skip backing tracks (already-generated accompaniment files)
              if (name.match(/_backingtrack\.(mp3|wav)$/i)) continue;
              if (!name.match(/\.(mp3|flac)$/i)) continue;
              const id = `path:${p}`;
              // Prefer music:// protocol in Electron to stream directly with range support
              const src = api ? `music://local/${encodeURIComponent(p)}` : undefined;
              arr.push({ id, name, path: p, src });
            }

      setTracks(prev => {
        const newTracks = [...prev, ...arr];
        setLogs(l=>[...l, `Added ${arr.length} files from path list`]);
        try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Added ${arr.length} files from path list: ${arr.map(a=>a.name).join(',')}`); } catch (e) {}
        console.log('addFilesFromPathList added', arr.map(a=>a.name));
        return newTracks;
      });

      // If music protocol not available, fall back to reading and creating blob URLs
      if (!api?.readFile) return;

      for (const t of arr) {
        (async () => {
          try {
            const statRes = await api.stat?.(t.path);
            if (statRes && statRes.ok && statRes.isFile) {
              // nothing else needed when music:// is used
              return;
            }
          } catch(_) {}

          try {
            const pathKey = t.path || '';
            const reqId = ((readRequestIdRef.current[pathKey] || 0) + 1);
            readRequestIdRef.current[pathKey] = reqId;

            const res = await api.readFile(t.path);
            if (readRequestIdRef.current[pathKey] !== reqId) {
              setLogs(l=>[...l, `stale readFile result ignored for ${t.path}`]);
            } else if (res && res.ok && res.data) {
              const binary = atob(res.data);
              const len = binary.length;
              const u8 = new Uint8Array(len);
              for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
              const blob = new Blob([u8], { type: res.mime || 'application/octet-stream' });
              const url = URL.createObjectURL(blob);
              // create a File object if supported (useful for chrome APIs)
              let fileObj: File | undefined = undefined;
              try { fileObj = new File([blob], t.name, { type: res.mime || 'application/octet-stream' }); } catch (e) { /* ignore if not supported */ }
                          // If current track matches, swap audio.src while preserving time/play state
                          setTracks(currentTracks => {
                            const updated = currentTracks.map(ct => ct.id === t.id ? { ...ct, src: url, file: fileObj } : ct);
                            try {
                              const curIdx = current;
                              if (curIdx != null) {
                                const curTrack = currentTracks[curIdx];
                                if (curTrack && curTrack.id === t.id && audioRef.current) {
                                  const wasPlaying = !audioRef.current.paused;
                                  const curTime = audioRef.current.currentTime || 0;
                                  try { audioRef.current.src = url; } catch(e) { /* ignore */ }
                                  try { audioRef.current.currentTime = Math.max(0, Math.min(curTime, audioRef.current.duration || curTime)); } catch(e) { }
                                  if (wasPlaying) {
                                    try { const p = audioRef.current.play(); if (p && typeof (p as any).then === 'function') p.catch(()=>{}); } catch(e) {}
                                  }
                                }
                              }
                            } catch(e) { console.warn('preserve audio src swap failed', e); }
                            return updated;
                          });
                          setLogs(l=>[...l, `Created blob for ${t.name}`]);
                          try { api.appendLog && api.appendLog(`Created blob for ${t.name}`); } catch(e){}
                          // try extract cover using the File object if available, otherwise use the Blob
                          const extractTarget: File | Blob = fileObj || blob;
                          extractCoverFromFile(extractTarget).then(urlCover => {
                            if (urlCover) setTracks(currentTracks => currentTracks.map(ct => ct.id === t.id ? { ...ct, cover: urlCover } : ct));
                          }).catch(err => { setLogs(l=>[...l, `cover extract error ${t.name}: ${String(err)}`]); });
                        } else {
                          setLogs(l=>[...l, `readFile failed for ${t.path}: ${res?.error || 'unknown'}`]);
                        }
          } catch (err) {
            setLogs(l=>[...l, `readFile exception ${String(err)}`]);
          }
        })();
      }

      // kick off auto-generate if enabled for path-added tracks
      if (autoGenerateBacking) {
        generateBackingForTracks(arr);
      }
    }

  async function onFiles(e: React.ChangeEvent<HTMLInputElement>) {
    if (!e.target.files) return;
    addFilesFromFileList(e.target.files);
  }

  async function onFolder(e: React.ChangeEvent<HTMLInputElement> | undefined) {
      // Prefer Electron folder chooser when available to avoid browser "upload all files" prompt
      if ((window as any).electronAPI?.chooseFolder) {
        try {
          const res = await (window as any).electronAPI.chooseFolder();
          if (res && res.canceled === false && Array.isArray(res.paths)) {
            for (const p of res.paths) {
              const r = await (window as any).electronAPI.readdirRecursive(p);
              if (r && r.ok && Array.isArray(r.files)) {
                const files = r.files.filter((f: string) => f.match(/\.(mp3|flac)$/i));
                await addFilesFromPathList(files);
              }
            }
          }
        } catch (err) { console.warn('chooseFolder failed', err); }
        return;
      }
      if (!e || !e.target || !e.target.files) return;
      // webkitdirectory gives all files inside
      addFilesFromFileList(e.target.files);
    }

  async function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    // reset drag counter/state reliably
    dragCounter.current = 0;
    setIsDragging(false);
    const dt = e.dataTransfer;
    if (!dt) return;
    if (dt.files && dt.files.length > 0) {
      addFilesFromFileList(dt.files);
      return;
    }
  }

  function onDragOver(e: React.DragEvent) { e.preventDefault(); }
  function onDragEnter(e: React.DragEvent) { e.preventDefault(); dragCounter.current++; if (dragCounter.current > 0) setIsDragging(true); }
  function onDragLeave(e: React.DragEvent) { e.preventDefault(); dragCounter.current = Math.max(0, dragCounter.current - 1); if (dragCounter.current === 0) setIsDragging(false); }

  function nextTrack() {
    const idx = current ?? -1;
    let next = idx + 1;
    if (next >= tracks.length) {
      if (loopPlaylist && tracks.length > 0) next = 0;
      else return;
    }
    playIndex(next);
  }

  function prevTrack() {
    const idx = current ?? 0;
    let prev = idx - 1;
    if (prev < 0) {
      if (loopPlaylist && tracks.length > 0) prev = tracks.length - 1;
      else return;
    }
    playIndex(prev);
  }

  async function setAudioSourceAndPlay(newSrc: string, idx: number) {
    try {
      if (shifterRef.current) {
        try { shifterRef.current.disconnect(); } catch(e) {}
        shifterRef.current = null as any;
      }
      if (audioRef.current) {
        try { audioRef.current.pause(); } catch(e) {}
        audioRef.current.src = newSrc;
        try { audioRef.current.currentTime = 0; } catch(e) {}
        await (audioCtxRef.current?.state === 'suspended' ? audioCtxRef.current.resume() : Promise.resolve());
        try { await audioRef.current.play(); } catch(e) { console.warn('play failed', e); }
        setIsPlaying(true);
        setCurrent(idx);
      }
    } catch(e) { console.warn('setAudioSourceAndPlay failed', e); }
  }

  async function playIndex(i: number) {
    const t = tracks[i];
    if (!t) return;
    // Stop any prior playback sources to avoid multiple progress updates racing
    try {
      if (shifterRef.current) {
        try { shifterRef.current.disconnect(); } catch(e){}
        shifterRef.current = null as any;
      }
    } catch(e) {}
    try { if (audioRef.current) { try { audioRef.current.pause(); } catch(e){} } } catch(e) {}
    setIsPlaying(false);

    let src: string | undefined;

    // If backingActive is set, prefer backing file in the same folder when available
    try {
      const api = (window as any).electronAPI;
      if (t.path && t.backingActive && api?.stat) {
        const pth = t.path.replace(/\\/g,'/');
        const dir = pth.replace(/\/[^\/]*$/,'');
        const base = (pth.split('/').pop() || '').replace(/\.[^/.]+$/, '');
        const candMp3 = dir + '/' + base + '_backingtrack.mp3';
        const candWav = dir + '/' + base + '_backingtrack.wav';
        try {
          const s1 = await api.stat(candMp3);
          if (s1 && s1.ok && s1.isFile) {
            src = `music://local/${encodeURIComponent(candMp3)}`;
          } else {
            const s2 = await api.stat(candWav);
            if (s2 && s2.ok && s2.isFile) src = `music://local/${encodeURIComponent(candWav)}`;
          }
        } catch(e) {
          // ignore and fallback to normal src resolution
        }
      }
    } catch(e) {}

    if (!src) {
      if (t.src) src = t.src;
      else if (t.path) {
        const api = (window as any).electronAPI;
        if (api) {
          // prefer streaming via music:// protocol which supports range requests
          src = `music://local/${encodeURIComponent(t.path)}`;
        } else {
          // normalize Windows paths into file URL (browser only)
          const p = t.path.replace(/\\/g, '/').replace(/^\/+/, '');
          src = `file:///${encodeURI(p)}`;
        }
      }
    }

    // If running in Electron and music protocol isn't available for some reason, keep previous readFile fallback
    try {
      const api = (window as any).electronAPI;
      if (src && src.startsWith('file://') && api?.readFile) {
        try {
            // create/read guard id for this path to avoid applying stale blobs
            const pathKey = t.path || '';
            const reqId = ((readRequestIdRef.current[pathKey]||0) + 1);
            readRequestIdRef.current[pathKey] = reqId;

            const res = await api.readFile(t.path);

            // if another read started after this one, ignore result
            if (readRequestIdRef.current[pathKey] !== reqId) {
              setLogs(l=>[...l, `stale recreate readFile result ignored for ${t.path}`]);
            } else if (res && res.ok && res.data) {
              const binary = atob(res.data);
              const len = binary.length;
              const u8 = new Uint8Array(len);
              for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
              const blob = new Blob([u8], { type: res.mime || 'application/octet-stream' });
              const url = URL.createObjectURL(blob);
              src = url;
              setTracks(prev => prev.map((pt, idx) => idx === i ? { ...pt, src: url } : pt));
            } else {
              setLogs(l=>[...l, `readFile failed for ${t.path}: ${res?.error || 'unknown'}`]);
            }
        } catch(err) {
          setLogs(l=>[...l, `readFile exception ${String(err)}`]);
        }
      }
    } catch(e) { }

    if (!src) return;
    // If blob URL fails (HMR or URL revoked), recreate it from the original File if available.
    try {
      if (src.startsWith('blob:')) {
        // If we have the original File object, recreate blob URL to ensure it's valid
        if (t.file) {
          try {
            const newUrl = URL.createObjectURL(t.file);
            src = newUrl;
            setTracks(prev => prev.map((pt, idx) => idx === i ? { ...pt, src: newUrl } : pt));
            setLogs(l=>[...l, `Recreated blob URL for ${t.name}`]);
            try{ (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Recreated blob URL for ${t.name}`); }catch{}
          } catch (e) { setLogs(l=>[...l, `recreate blob error ${String(e)}`]); }
        } else if (t.path && (window as any).electronAPI?.readFile) {
          // As a last resort, read file again from disk and create blob
          try {
            const pathKey = t.path || '';
            const reqId = ((readRequestIdRef.current[pathKey] || 0) + 1);
            readRequestIdRef.current[pathKey] = reqId;

            const res = await (window as any).electronAPI.readFile(t.path);
            if (readRequestIdRef.current[pathKey] !== reqId) {
              setLogs(l=>[...l, `stale recreate readFile result ignored for ${t.path}`]);
            } else if (res && res.ok && res.data) {
              const binary = atob(res.data);
              const len = binary.length;
              const u8 = new Uint8Array(len);
              for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
              const blob = new Blob([u8], { type: res.mime || 'application/octet-stream' });
              const url = URL.createObjectURL(blob);
              src = url;
              setTracks(prev => prev.map((pt, idx) => idx === i ? { ...pt, src: url } : pt));
              setLogs(l=>[...l, `Recreated blob URL from disk for ${t.name}`]);
            }
          } catch (e) { setLogs(l=>[...l, `readFile recreate error ${String(e)}`]); }
        }
      }
    } catch(e) { /* ignore */ }

    // If cover missing for this track, attempt to extract from file/blob now so UI can show it during playback
    try {
      if (!t.cover) {
        const api = (window as any).electronAPI;
        let extractTarget: File | Blob | undefined;
        if (src && src.startsWith('blob:') && t.file) {
          extractTarget = t.file;
        } else if (t.path && api?.readFile) {
          try {
            const rf = await api.readFile(t.path);
            if (rf && rf.ok && rf.data) {
              const binary = atob(rf.data);
              const len = binary.length;
              const u8 = new Uint8Array(len);
              for (let j = 0; j < len; j++) u8[j] = binary.charCodeAt(j);
              const blob = new Blob([u8], { type: rf.mime || 'application/octet-stream' });
              extractTarget = blob;
              try { t.file = new File([blob], t.name, { type: rf.mime || 'application/octet-stream' }); } catch(e) { /* ignore */ }
            }
          } catch(e) { /* ignore */ }
        }
        if (extractTarget) {
          const cov = await extractCoverFromFile(extractTarget as any);
          if (cov) {
            setTracks(prev => prev.map((pt, idx) => idx === i ? { ...pt, cover: cov } : pt));
            setLogs(l=>[...l, `Extracted cover for ${t.name} on play`]);
          }
        }
      }
    } catch(e) { setLogs(l=>[...l, `cover extract on play error: ${String(e)}`]); }

    console.log('Attempting play', { index: i, track: t, src });
    try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Attempting play index=${i} name=${t.name}`); } catch (e) { try{ setLogs(l=>[...l, 'appendLog failed: ' + String(e)]); } catch{} }
    if (src.startsWith('file://') && !(window as any).electronAPI) {
      // In browser contexts file:// is not allowed for security reasons.
      alert('Cannot play local file paths in the browser. Use "Add Files" so the file is loaded as a blob, or run the Electron app.');
      return;
    }

    if (playLockRef.current) {
      setLogs(l => [...l, `Play request ignored due to ongoing play operation`]);
      return;
    }
    playLockRef.current = true;

    // Ensure AudioContext and nodes exist
    try {
      if (!audioCtxRef.current) {
        const C = (window as any).AudioContext || (window as any).webkitAudioContext;
        const ctx = new C();
        audioCtxRef.current = ctx;
        const panner = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
        pannerRef.current = panner;
        const gain = ctx.createGain();
        gainRef.current = gain;
        if (panner) { panner.connect(gain); }
        gain.connect(ctx.destination);
        try { gain.gain.value = volume; } catch(e){}
      }
    } catch(e) {
      console.warn('AudioContext init failed', e);
    }

    // Attempt to use soundtouchjs PitchShifter for tempo-preserving pitch changes. If unavailable, fallback to <audio> playback.
    let usedPitchShifter = false;
    try {
      const stMod = await import('soundtouchjs');
      const PitchShifter = (stMod as any).PitchShifter;
      if (PitchShifter && audioCtxRef.current && gainRef.current) {
        try {
          // fetch and decode source into AudioBuffer
          const arr = await fetch(src).then(r => r.arrayBuffer());
          const audioBuf = await audioCtxRef.current.decodeAudioData(arr);
          // clean up any previous shifter
          try { shifterRef.current?.disconnect(); } catch(e){}
          const shifter = new (PitchShifter as any)(audioCtxRef.current, audioBuf, 16384, () => { try { if (autoNext) { nextTrack(); } else { setIsPlaying(false); } } catch(e) {} });
          shifter.tempo = 1;
          shifter.pitchSemitones = transpose || 0;
          // connect to existing gain/panner chain
          if (pannerRef.current) shifter.connect(pannerRef.current); else shifter.connect(gainRef.current);

          // wire up progress events
          shifter.on('play', (detail: any) => {
            try { if (!seekingRef.current) setSeekTime(detail.timePlayed); } catch(e){}
            try { setDuration(shifter.duration || detail.duration || duration); } catch(e){}
          });

          // start playback
          await (audioCtxRef.current.state === 'suspended' ? audioCtxRef.current.resume() : Promise.resolve());
          shifterRef.current = shifter;
          setCurrent(i);
          setIsPlaying(true);
          // Attach lyrics poller when pitch shifter starts so lyrics/seek stay in sync
          try { attachLyricsTimeListener(); } catch(e) { /* ignore */ }
          // Prefetch lyrics for this track so UI shows lyrics when using PitchShifter
          try {
            const found = await getLyricsForTrack(t);
            setLyricsMode(found ? 'synchronized' : 'static');
          } catch (e) { console.warn('getLyricsForTrack failed', e); }
          setLogs(l=>[...l, `PitchShifter playback started for ${t.name}`]);
          usedPitchShifter = true;
        } catch (err) {
          console.warn('PitchShifter init failed', err);
          setLogs(l=>[...l, `PitchShifter failed: ${String(err)}`]);
        }
      }
    } catch (e) {
      // dynamic import failed - not fatal, fall back to audio element
      console.log('soundtouchjs not available, falling back to <audio> element');
    }

    if (!usedPitchShifter && audioRef.current) {
      // Fallback: keep existing <audio> element playback
      try {
        // basic support check by extension
        const ext = (t.name || '').split('.').pop()?.toLowerCase();
        const mime = ext === 'mp3' ? 'audio/mpeg' : ext === 'flac' ? 'audio/flac' : '';
        try {
          const can = (mime && audioRef.current.canPlayType) ? audioRef.current.canPlayType(mime) : '';
          setLogs(l=>[...l, `canPlayType(${mime})=${can}`]);
        } catch (e) { setLogs(l=>[...l, `canPlayType check error: ${String(e)}`]); }

        // Reset position to start if possible.
        try { audioRef.current.currentTime = 0; } catch (e) {}
        // clear previous sources
        audioRef.current.removeAttribute('src');
        while (audioRef.current.firstChild) audioRef.current.removeChild(audioRef.current.firstChild as Node);
        if (mime) {
          const srcEl = document.createElement('source');
          srcEl.src = src;
          srcEl.type = mime;
          audioRef.current.appendChild(srcEl);
        } else {
          audioRef.current.src = src;
        }
        audioRef.current.load();
        const p = audioRef.current.play();
        if (p !== undefined && typeof (p as any).then === 'function') {
          (p as any).then(async () => { setCurrent(i); try{ (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Playback started index=${i} name=${t.name}`); }catch{}
                          // prefetch lyrics when playback starts
                          try { const found = await getLyricsForTrack(t); if (found) setLyricsMode('synchronized'); else setLyricsMode('static'); } catch(e) {}
                        })
                      .catch((err: any) => {
              console.error('Playback failed', err);
              setLogs(l=>[...l, 'Playback failed: ' + String((err as any))]);
                            try{ (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Playback failed index=${i} error=${String((err as any))}`); }catch{}
              // Ignore benign aborts caused by an immediate pause interrupting play()
                            const msg = (err && (((err as any).message) || ((err as any).name) || String(err))).toString();
              if (!/interrupted|aborted|abort/i.test(msg)) {
                              alert('Playback failed: ' + String((err as any)));
              } else {
                setLogs(l=>[...l, 'Ignored abort/interrupted play(): ' + msg]);
              }
            }).finally(() => { playLockRef.current = false; });
        } else {
          setCurrent(i);
          playLockRef.current = false;
        }
      } catch (err) {
        console.error('play error', err);
        setLogs(l=>[...l, 'play error: ' + String((err as any))]);
                alert('Playback failed: ' + String((err as any)));
      } finally {
        // ensure lock is released in case of synchronous errors
        playLockRef.current = false;
      }
    } else {
      // started via PitchShifter
      playLockRef.current = false;
    }
  }

  function playSelected() {
    const idx = selected ?? current;
    if (idx === null || idx === undefined) return;
    playIndex(idx);
  }

  function getNextPlaylistName() {
      // names like playlist1, playlist2 (case-insensitive)
      const used = new Set(playlists.map(p => (p.name || '').toLowerCase()));
      let max = 0;
      for (const n of used) {
        const m = n.match(/^playlist(\d+)$/i);
        if (m) {
          const v = parseInt(m[1], 10);
          if (!isNaN(v) && v > max) max = v;
        }
      }
      let candidate: string;
      do {
        candidate = `playlist${max + 1}`;
        max++;
      } while (used.has(candidate.toLowerCase()));
      return candidate;
    }

    async function savePlaylist() {
      // If user has selected an existing playlist, overwrite it.
      // Otherwise auto-generate a new sequential name like playlist1, playlist2.
      let name = selectedPlaylistName || '';
      const isExisting = !!playlists.find(p => p.name === name);
      if (!isExisting) {
        name = getNextPlaylistName();
      }

      // create a serializable copy of tracks (strip File and other non-cloneable objects)
      const serializableTracks = tracks.map(t => ({ id: t.id, name: t.name, path: t.path, src: t.src, cover: t.cover }));

      if ((window as any).electronAPI?.savePlaylist) {
        try {
          const res = await (window as any).electronAPI.savePlaylist(name, serializableTracks);
          try { (window as any).electronAPI?.appendLog && (window as any).electronAPI.appendLog(`Saved playlist ${name} via electron`); } catch (e) {}
          if (!res.ok) alert('Save failed: ' + res.error);
          else {
            // update local state to reflect saved playlist
            setPlaylists(prev => {
              const rest = prev.filter(p => p.name !== name);
              return [...rest, { name, tracks: serializableTracks }];
            });
            setSelectedPlaylistName(name);
            try { localStorage.setItem('defaultPlaylistName', name); } catch {}
            // no intrusive alert: show small confirmation
            setLogs(l=>[...l, `Saved playlist ${name}`]);
          }
        } catch (e) { console.warn('electron save failed', e); alert('Save failed: ' + String(e)); }
      } else {
        // fallback: save to localStorage
        try {
          const cur = JSON.parse(localStorage.getItem('playlists') || '[]');
          const rest = (Array.isArray(cur) ? cur.filter((p:any)=>p.name !== name) : []);
          const store = [...rest, { name, tracks: serializableTracks }];
          localStorage.setItem('playlists', JSON.stringify(store));
          setPlaylists(store);
          setSelectedPlaylistName(name);
          try { localStorage.setItem('defaultPlaylistName', name); } catch {}
          setLogs(l=>[...l, `Saved playlist ${name} locally`]);
        } catch (e) { alert('Save failed: ' + e); }
      }
    }

    function openRenameModal() {
      if (!selectedPlaylistName) { alert('No playlist selected to rename'); return; }
      setRenameValue(selectedPlaylistName);
      setRenameTarget(selectedPlaylistName);
      setRenameModalOpen(true);
    }

    async function confirmRename() {
      const oldName = renameTarget;
      const newName = (renameValue || '').trim();
      if (!oldName) { alert('No playlist selected to rename'); setRenameModalOpen(false); return; }
      if (!newName || newName === oldName) { setRenameModalOpen(false); return; }
      // avoid name collisions
      if (playlists.find(p => p.name === newName)) { alert('A playlist with that name already exists'); return; }

      const updated = playlists.map(p => p.name === oldName ? { ...p, name: newName } : p);
      setPlaylists(updated);
      setSelectedPlaylistName(newName);
      try { localStorage.setItem('playlists', JSON.stringify(updated)); } catch(e){}
      try { localStorage.setItem('defaultPlaylistName', newName); } catch(e){}

      // persist to disk if electron available
      try {
        const api = (window as any).electronAPI;
        if (api?.writePlaylists) {
          const res = await api.writePlaylists(updated);
          if (res?.ok) setLogs(l=>[...l, `Renamed playlist ${oldName} -> ${newName}`]);
          else setLogs(l=>[...l, `writePlaylists failed: ${res?.error}`]);
        } else if (api?.savePlaylist) {
          for (const p of updated) {
            await api.savePlaylist(p.name, p.tracks);
          }
          setLogs(l=>[...l, `Renamed (via per-save) ${oldName} -> ${newName}`]);
        }
      } catch (err) { setLogs(l=>[...l, `rename persist error: ${String(err)}`]); }

      setRenameModalOpen(false);
      setRenameTarget(null);
    }

    function cancelRename() {
      setRenameModalOpen(false);
      setRenameTarget(null);
    }

    async function deletePlaylist() {
      if (!selectedPlaylistName) { alert('No playlist selected to delete'); return; }
      const name = selectedPlaylistName;
      if (!confirm(`Delete playlist "${name}"? This cannot be undone.`)) return;
      const updated = playlists.filter(p => p.name !== name);
      setPlaylists(updated);
      setSelectedPlaylistName(null);
      setTracks([]);
      try { localStorage.setItem('playlists', JSON.stringify(updated)); } catch(e){}
      try { localStorage.removeItem('defaultPlaylistName'); } catch(e){}
      try {
        const api = (window as any).electronAPI;
        if (api?.writePlaylists) {
          const res = await api.writePlaylists(updated);
          if (res?.ok) setLogs(l=>[...l, `Deleted playlist ${name}`]);
          else setLogs(l=>[...l, `writePlaylists failed: ${res?.error}`]);
        } else if (api?.savePlaylist) {
          // delete by saving each remaining playlist (per-save fallback)
          for (const p of updated) {
            await api.savePlaylist(p.name, p.tracks);
          }
          setLogs(l=>[...l, `Deleted (via per-save) playlist ${name}`]);
        }
      } catch(err) { setLogs(l=>[...l, `delete persist error: ${String(err)}`]); }
    }

  // cleanup blob URLs on unmount
  useEffect(() => {
    return () => {
      for (const t of tracks) {
        if (t.src && t.src.startsWith('blob:')) URL.revokeObjectURL(t.src);
      }
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const activeTrackIndex = current ?? selected;
  const activeTrack = activeTrackIndex == null ? null : tracks[activeTrackIndex] ?? null;
  const backingToggleEnabled = !!activeTrack?.path && !!backingAvailableMap[activeTrack.id];

  return (
    <div className="app" role="application" aria-label="MintPlayer" style={{ background: 'radial-gradient(circle at top, #2b2931 0%, #17181d 28%, #0c0d10 100%)', color: '#f5f7fb', gap: 20, padding: '18px 18px 26px', height: '100vh', boxSizing: 'border-box' }}>

      <aside className={`playlists${isDragging ? ' drop-active' : ''}`} role="navigation" aria-label="Playlists" style={{ width: '20%', minWidth: 180, fontSize: '0.85rem', background: 'rgba(17,18,23,0.92)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 24, boxShadow: '0 18px 40px rgba(0,0,0,0.32)', color: '#eef2ff', padding: '18px 18px 8px', backdropFilter: 'blur(10px)', display: 'flex', flexDirection: 'column', flex: '0 0 24%', minHeight: 0, maxHeight: 'calc(100vh - 36px)' }} onDrop={handleDrop} onDragOver={onDragOver} onDragEnter={onDragEnter} onDragLeave={onDragLeave}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 10 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            <select value={selectedPlaylistName || ''} onChange={(e)=>{
                const v = e.target.value || null;
                console.log('playlist select changed', v);
                setLogs(l=>[...l, `Playlist select changed: ${v}`]);
                setSelectedPlaylistName(v);
                try { localStorage.setItem('defaultPlaylistName', v || ''); } catch {}
                if (v) {
                  const p = playlists.find(pl=>pl.name === v);
                  if (p) setTracks(p.tracks || []);
                }
              }} aria-label="Select playlist" style={{ background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.08)', color: '#f5f7fb', borderRadius: 10, padding: '8px 12px', minWidth: 110, flex: 1 }}>
                {playlists.map(pl => <option key={pl.name} value={pl.name} style={{ background: '#121418', color: '#f5f7fb' }}>{pl.name}</option>)}
              </select>
            <button className="icon-btn" style={{ marginLeft: 0, background: 'rgba(255,255,255,0.06)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }} onClick={openRenameModal} aria-label="Edit playlist" title="Edit playlist">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04a1.003 1.003 0 000-1.42l-2.34-2.34a1.003 1.003 0 00-1.42 0l-1.83 1.83 3.75 3.75 1.84-1.82z" fill="currentColor"/></svg>
            </button>
            <button className="icon-btn" style={{ marginLeft: 0, background: 'rgba(255,255,255,0.06)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }} onClick={deletePlaylist} aria-label="Delete playlist" title="Delete playlist">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M6 19a2 2 0 002 2h8a2 2 0 002-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z" fill="currentColor"/></svg>
            </button>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, flex: 1 }}>
              <input ref={addFilesInputRef} id="addFilesInput" type="file" multiple style={{ display: 'none' }} onChange={onFiles} />
              <input ref={addFolderInputRef} id="addFolderInput" type="file" {...({'webkitdirectory':'true'} as any)} style={{ display: 'none' }} onChange={onFolder as any} />

              <button className="icon-btn" onClick={()=> addFilesInputRef.current?.click()} aria-label="Add files" title="Add files" style={{ background: 'linear-gradient(135deg, #ff9c4b, #ff6b6b)', color: '#fff', border: 'none', boxShadow: '0 12px 28px rgba(255, 118, 66, 0.35)' }}>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M19 13h-4v4H9v-4H5l7-7 7 7zM5 20h14v2H5z" fill="currentColor"/></svg>
              </button>
              <button className="icon-btn" style={{ marginLeft: 0, background: 'rgba(255,255,255,0.06)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }} onClick={()=>{ const win = (window as any).electronAPI; if (win?.chooseFolder) { (async ()=>{ await onFolder(undefined as any); })(); } else { addFolderInputRef.current?.click(); } }} aria-label="Add folder" title="Add folder">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M10 4H4a2 2 0 00-2 2v12a2 2 0 002 2h16a2 2 0 002-2V8a2 2 0 00-2-2h-8l-2-2zM12 12v4h-2v-4H8l4-4 4 4h-2z" fill="currentColor"/></svg>
              </button>
              <button className="icon-btn" style={{ marginLeft: 0, background: 'rgba(255,255,255,0.06)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }} onClick={savePlaylist} aria-label="Save playlist" title="Save playlist">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M17 3H5a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2V7l-4-4zM12 17a3 3 0 110-6 3 3 0 010 6zm5-9H7V5h10v3z" fill="currentColor"/></svg>
              </button>
            </div>

            <button className="icon-btn" style={{ marginLeft: 0, background: 'rgba(255,255,255,0.06)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }} onClick={() => setView(view === 'config' ? 'player' : 'config')} aria-label="Settings" title="Settings">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 8a4 4 0 100 8 4 4 0 000-8zm8.94 3a6.96 6.96 0 00-.11-1l2.03-1.57-2-3.46-2.39.96a6.9 6.9 0 00-1.3-.75l-.36-2.54H9.2l-.36 2.54c-.43.22-.85.48-1.24.77L4.15 7.43l-2 3.46 2.03 1.57c-.06.33-.06.67-.06 1s0 .67.06 1L2.15 16.9l2 3.46 2.39-.96c.39.29.81.55 1.24.77l.36 2.54h5.09l.36-2.54c.45-.22.9-.48 1.3-.75l2.39.96 2-3.46-2.03-1.57c.06-.33.11-.67.11-1z" fill="currentColor"/></svg>
            </button>
          </div>
        </div>
        {isDragging && <div className="drop-overlay">Drop files or folder here</div>}
        <div className="drop-zone" style={{ background: 'rgba(255,255,255,0.02)', borderRadius: 18, border: '1px solid rgba(255,255,255,0.04)', padding: 8, flex: '1 1 auto', minHeight: 0, display: 'flex', flexDirection: 'column' }}>
          {isDragging && <div className="drop-overlay">Drop files or folder here</div>}
          <ul role="listbox" aria-label="Tracks" className="track-list">
            {tracks.map((t, i) => (
              <li
                key={i}
                role="option"
                aria-selected={selected===i}
                tabIndex={0}
                onKeyDown={(e)=>{ if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setSelected(i); playIndex(i); } }}
                onClick={()=>{ setSelected(i); playIndex(i); }}
              >
                {t.name}{t.path ? ` — ${t.path}` : ''}
              </li>
            ))}
          </ul>
        </div>
      </aside>

      <main className="player" role="main" aria-label="Player" style={{ flex: '1 1 auto', minWidth: 0, display: 'flex', flexDirection: 'column', gap: 18, minHeight: 0, height: '100%' }}>
        {view === 'config' ? (
          <div style={{ background: 'rgba(18,18,23,0.92)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 24, padding: 24, boxShadow: '0 18px 40px rgba(0,0,0,0.32)' }}>
            <h2 style={{ marginTop: 0, color: '#f5f7fb' }}>Configuration</h2>
            <div style={{ marginBottom: 12 }}>
              <label style={{ display: 'block', marginBottom: 10, color: '#eef2ff' }}>
                <input type="checkbox" checked={showCover} onChange={(e)=>{ const v = e.target.checked; setShowCover(v); try{ localStorage.setItem('showCover', String(v)); }catch{} }} /> Show cover in player
              </label>
              <label style={{ display: 'block', marginBottom: 10, color: '#eef2ff' }}>
                <input type="checkbox" checked={autoGenerateBacking} onChange={(e)=>{ const v = e.target.checked; setAutoGenerateBacking(v); try{ localStorage.setItem('autoGenerateBacking', String(v)); }catch{} }} /> Auto-generate backing tracks when adding files/folders
              </label>
              <label style={{ display: 'block', marginBottom: 10, color: '#eef2ff' }}>
                <input type="checkbox" checked={autoNext} onChange={(e)=>{ const v = e.target.checked; setAutoNext(v); try{ localStorage.setItem('autoNext', String(v)); }catch{} }} /> Auto play next
              </label>
              <label style={{ display: 'block', marginBottom: 10, color: '#eef2ff' }}>
                <input type="checkbox" checked={loopPlaylist} onChange={(e)=>{ const v = e.target.checked; setLoopPlaylist(v); try{ localStorage.setItem('loopPlaylist', String(v)); }catch{} }} /> Loop playlist when finished
              </label>
            </div>
            <div>
              <button onClick={()=>setView('player')} style={{ borderRadius: 12, border: '1px solid rgba(255,255,255,0.12)', background: '#1d1f27', color: '#f5f7fb', padding: '10px 14px' }}>Back to Player</button>
            </div>
          </div>
        ) : (
          <>
            <div className="media-stage" style={{ display: 'flex', gap: 18, alignItems: 'stretch', flex: '1 1 auto', minHeight: 500, height: '100%', minWidth: 0 }}>
              <div style={{ position: 'relative', flex: 1, minWidth: 260, minHeight: 500, borderRadius: 24, boxShadow: '0 28px 60px rgba(0,0,0,0.32)', background: 'linear-gradient(135deg, #f6d38c 0%, #ff8f70 40%, #7a5cff 100%)', overflow: 'hidden' }}>
                <div style={{ position: 'absolute', left: 14, top: 14, zIndex: 20, display: 'flex', alignItems: 'center', gap: 12 }}>
                  <button
                    type="button"
                    onClick={() => setMediaFront((v) => v === 'lyrics' ? 'cover' : 'lyrics')}
                    style={{
                      padding: '10px 14px',
                      borderRadius: 12,
                      border: '1px solid rgba(255,255,255,0.12)',
                      background: 'rgba(255,255,255,0.04)',
                      color: '#f5f7fb',
                      fontWeight: 700,
                      cursor: 'pointer',
                      boxShadow: '0 12px 26px rgba(0,0,0,0.18)',
                      minWidth: 94,
                    }}
                  >
                    {mediaFront === 'lyrics' ? 'cover' : 'lyrics'}
                  </button>
                  <button
                    type="button"
                    onClick={() => setLyricsMode((v) => v === 'static' ? 'synchronized' : 'static')}
                    style={{
                      padding: '10px 14px',
                      borderRadius: 12,
                      border: '1px solid rgba(255,255,255,0.12)',
                      background: 'rgba(255,255,255,0.04)',
                      color: '#f5f7fb',
                      fontWeight: 700,
                      cursor: 'pointer',
                      boxShadow: '0 12px 26px rgba(0,0,0,0.18)',
                      minWidth: 110,
                    }}
                  >
                    {lyricsMode === 'static' ? 'static' : 'synchronized'}
                  </button>
                </div>
                {showCover && (
                  <div style={{ position: 'absolute', inset: 0, zIndex: mediaFront === 'cover' ? 2 : 1, opacity: 1, transition: 'opacity 0.18s ease' }}>
                    {current != null && tracks[current] && tracks[current].cover ? (
                      <img src={tracks[current].cover} alt="cover" style={{ width: '100%', height: '100%', objectFit: 'contain', display: 'block', background: 'rgba(13,15,20,0.18)' }} />
                    ) : (
                      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', width: '100%', height: '100%', color: '#fff', fontWeight: 700, letterSpacing: 0.4 }}>Cover</div>
                    )}
                  </div>
                )}
                <div style={{ position: 'absolute', inset: 0, zIndex: mediaFront === 'lyrics' ? 2 : 1, background: 'rgba(17,18,23,0.68)', borderRadius: 24, border: '1px solid rgba(255,255,255,0.06)', boxShadow: '0 18px 40px rgba(0,0,0,0.24)', padding: 18, opacity: mediaFront === 'lyrics' ? 1 : 0.82, transition: 'opacity 0.18s ease' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12, gap: 8 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }} />
                    <strong style={{ fontSize: '1rem', color: '#f5f7fb' }}>Lyrics</strong>
                  </div>
                  <div ref={lyricsContainerRef} style={{ maxHeight: 'calc(100% - 70px)', overflow: 'auto', background: 'rgba(255,255,255,0.02)', padding: 12, borderRadius: 16, border: '1px solid rgba(255,255,255,0.04)' }}>
                    {lyricsMode === 'static' ? (
                      <pre style={{ whiteSpace: 'pre-wrap', margin: 0, fontSize: '0.95rem', lineHeight: 1.7, color: '#edf3ff' }}>{(lyricsRaw) ? lyricsRaw : (lyricsTimed ? lyricsTimed.map(l=>l.text).join('\n') : 'No lyrics found')}</pre>
                    ) : (
                      <div>
                        {lyricsTimed && lyricsTimed.length ? (
                          lyricsTimed.map((l, i) => (
                            <div id={`lyr-line-${i}`} key={i} role="button" tabIndex={0} aria-label={`Seek to ${formatTime(l.time)}`} onClick={()=>seekAndPlay(l.time)} onKeyDown={(e)=>{ if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); seekAndPlay(l.time); } }} className="lyric-line" style={{ padding: '9px 10px', background: (i === lyricsIndex) ? 'linear-gradient(135deg, rgba(255,156,75,0.24), rgba(255,107,107,0.14))' : 'transparent', borderRadius: 10, transition: 'background 0.08s', fontWeight: (i === lyricsIndex) ? 800 : 400, color: (i===lyricsIndex)?'#fff':'#dfe6f4', cursor: 'pointer', marginBottom: 2 }}>
                              <span style={{ color: '#cdd9f8', marginRight: 10, fontFamily: 'monospace', fontSize: '0.78rem' }}>{`${Math.floor(l.time/60)}:${String(Math.floor(l.time%60)).padStart(2,'0')}`}</span>
                              <span style={{ fontSize: (i===lyricsIndex)? '1.05em' : '1em' }}>{l.text}</span>
                            </div>
                          ))
                        ) : (
                          <pre style={{ whiteSpace: 'pre-wrap', margin: 0, fontSize: '0.95rem', lineHeight: 1.7, color: '#edf3ff' }}>{lyricsRaw || 'No synchronized lyrics found'}</pre>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>

            <div className="player-bottom" style={{ display: 'flex', flexDirection: 'column', gap: 12, flex: '0 0 auto', minHeight: 0, minWidth: 0, width: '100%' }}>

              <div className="player-toolbar" style={{ display: 'flex', alignItems: 'center', gap: 12, width: '100%', minHeight: 52, flexWrap: 'wrap', background: 'rgba(17,18,23,0.9)', borderRadius: 22, border: '1px solid rgba(255,255,255,0.06)', padding: '12px 14px', boxShadow: '0 18px 40px rgba(0,0,0,0.25)', backdropFilter: 'blur(10px)' }}>
                <div className="seek" aria-label="Seek controls" style={{ display: 'flex', alignItems: 'center', gap: 8, flex: '1 1 260px', minWidth: 200 }}>
                  <span className="time" style={{ minWidth: 42, fontSize: '0.82rem', textAlign: 'center', color: '#dfe6f4' }}>{formatTime(seekTime)}</span>
                  <input type="range" min={0} max={Math.max(0, duration)} step={0.1} value={seekTime} onChange={(e)=>{ const v = Number(e.target.value); setSeekTime(v); try { if (shifterRef.current) { const dur = shifterRef.current.duration || duration || 0; const perc = dur ? Math.max(0, Math.min(1, v / dur)) : 0; try { shifterRef.current.percentagePlayed = perc; } catch(e){} } else if (audioRef.current) { try{ audioRef.current.currentTime = v; } catch(e){} } } catch(e) { console.warn('seek input change failed', e); } }} aria-label="Seek" style={{ flex: 1 }} />
                  <span className="time" style={{ minWidth: 42, fontSize: '0.82rem', textAlign: 'center', color: '#dfe6f4' }}>{formatTime(duration)}</span>
                </div>

                <div className="transport-actions" style={{ display: 'flex', alignItems: 'center', gap: 8, flex: '0 0 auto' }}>
                  <button className="icon-btn" onClick={prevTrack} aria-label="Previous" style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M11 18V6l-8.5 6L11 18zM22 6v12h-2V6h2z" fill="currentColor"/></svg>
                  </button>

                  <button
                    type="button"
                    className="icon-btn"
                    onClick={toggleBackingTrack}
                    aria-label="Toggle backing track"
                    title="Toggle backing track"
                    style={{
                      background: backingAvailableMap[(current ?? selected ?? -1) !== null && (current ?? selected ?? -1) !== undefined ? tracks[current ?? selected ?? 0]?.id || '' : ''] ? 'linear-gradient(135deg, #ff9c4b, #ff6b6b)' : 'rgba(255,255,255,0.05)',
                      color: '#f5f7fb',
                      border: '1px solid rgba(255,255,255,0.08)',
                      boxShadow: 'none',
                      fontWeight: 800,
                      fontSize: '0.9rem'
                    }}
                  >
                    B
                  </button>

                  <button className="icon-btn" onClick={nextTrack} aria-label="Next" style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M13 6v12l8.5-6L13 6zM2 18V6h2v12H2z" fill="currentColor"/></svg>
                  </button>
                </div>

                <div className="audio-controls" style={{ display: 'flex', alignItems: 'center', gap: 10, marginLeft: 0, flex: '1 1 220px', minWidth: 200, flexWrap: 'wrap' }}>
                  <button className="icon-btn" onClick={()=>{ if (volume > 0) { prevVolumeRef.current = volume; setVolume(0); } else { setVolume(prevVolumeRef.current || 1); } }} aria-label="Mute" style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>
                    {volume > 0 ? (
                      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5 9v6h4l5 4V5l-5 4H5z" fill="currentColor"/></svg>
                    ) : (
                      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M16.5 12l4.5 4.5L19.5 20 15 15.5 10.5 20 8.5 18 13 13.5 8.5 9 10.5 7 15 11.5 19.5 7 21 8.5 16.5 12z" fill="currentColor"/></svg>
                    )}
                  </button>
                  <input aria-label="Volume" type="range" min={0} max={1} step={0.01} value={volume} onChange={(e)=>{ const v = Number(e.target.value); setVolume(v); if (audioRef.current) try{ audioRef.current.volume = v; } catch(e){} }} style={{ width: 100 }} />
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: 8, flex: '0 0 auto', minWidth: 0, flexWrap: 'nowrap' }}>
                  <div className="pan-panel" style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 10px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 12, minWidth: 0, whiteSpace: 'nowrap' }}>
                    <label style={{ fontSize: '0.82rem', color: '#dfe6f4', fontWeight: 600 }}>Pan</label>
                    <input aria-label="Pan" type="range" min={-1} max={1} step={0.01} value={pan} onChange={(e)=>{ const v = Number(e.target.value); setPan(v); if (pannerRef.current) try{ pannerRef.current.pan.value = v; } catch(e){} }} style={{ width: 90, accentColor: '#ff9c4b' }} />
                  </div>

                  <div className="transpose-panel" style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 10px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 12, minWidth: 0, whiteSpace: 'nowrap' }}>
                    <button className="icon-btn" onClick={()=>setTranspose(-12)} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>-12</button>
                    <button className="icon-btn" onClick={()=>setTranspose(t=>Math.max(-12, t-1))} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>-1</button>
                    <div style={{ padding: '6px 10px', background: 'rgba(255,255,255,0.05)', borderRadius: 10, minWidth: 48, textAlign: 'center', fontWeight: 700, color: '#fff', border: '1px solid rgba(255,255,255,0.04)' }}>{transpose >= 0 ? '+'+transpose : transpose}</div>
                    <button className="icon-btn" onClick={()=>setTranspose(t=>Math.min(12, t+1))} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>+1</button>
                    <button className="icon-btn" onClick={()=>setTranspose(12)} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>+12</button>
                    <input type="range" min={-12} max={12} step={1} value={transpose} onChange={(e)=>setTranspose(Number(e.target.value))} aria-label="Transpose" style={{ width: 120, accentColor: '#ff9c4b' }} />
                  </div>
                </div>
              </div>
              <audio ref={audioRef} onError={(e)=>{ const a = e.currentTarget as HTMLAudioElement; console.error('audio error', a.error); setLogs(l=>[...l, 'audio error: ' + String(a.error?.message || a.error?.code || a.error || 'unknown')]); }} style={{ display: 'none', marginTop: 0, filter: 'sepia(0.2) saturate(1.2) brightness(1.05)' }} />

              <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                <button type="button" onClick={()=>setShowDebug((v)=>!v)} style={{ padding: '7px 12px', borderRadius: 10, border: '1px solid rgba(255,255,255,0.12)', background: 'rgba(255,255,255,0.04)', color: '#f5f7fb' }}>{showDebug ? 'Hide debug' : 'Show debug'}</button>
              </div>
              {showDebug && (
                <div style={{ background: 'rgba(17,18,23,0.9)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 20, padding: 16 }}>
                  <strong style={{ color: '#f5f7fb' }}>Debug:</strong>
                  <div style={{ display: 'flex', gap: 12, alignItems: 'flex-start', marginBottom: 8, marginTop: 8 }}>
                    <div style={{ flex: 1, maxHeight: 220, overflow: 'auto', background: '#0d0f15', padding: 8, borderRadius: 12, border: '1px solid rgba(255,255,255,0.08)' }}>
                      <pre style={{ whiteSpace: 'pre-wrap', color: '#dfe6f4', margin: 0 }}>{JSON.stringify(tracks.map(t=>({ id: t.id, name: t.name, hasFile: !!t.file, hasCover: !!t.cover, src: t.src })), null, 2)}</pre>
                    </div>
                    <div style={{ width: 240 }}>
                      <div style={{ marginBottom: 8 }}>
                        <label style={{ marginRight: 8, color: '#dfe6f4' }}>Transpose (semitones)</label>
                        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                          <button className="icon-btn" onClick={()=>setTranspose(-12)} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>-12</button>
                          <button className="icon-btn" onClick={()=>setTranspose(t=>Math.max(-12, t-1))} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>-1</button>
                          <div style={{ padding: '6px 10px', background: 'rgba(255,255,255,0.05)', borderRadius: 10, minWidth: 48, textAlign: 'center', color: '#fff' }}>{transpose >= 0 ? '+'+transpose : transpose}</div>
                          <button className="icon-btn" onClick={()=>setTranspose(t=>Math.min(12, t+1))} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>+1</button>
                          <button className="icon-btn" onClick={()=>setTranspose(12)} style={{ background: 'rgba(255,255,255,0.05)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', boxShadow: 'none' }}>+12</button>
                        </div>
                        <input type="range" min={-12} max={12} step={1} value={transpose} onChange={(e)=>setTranspose(Number(e.target.value))} style={{ width: '100%', marginTop: 8 }} />
                      </div>
                      <div style={{ fontSize: 12, color: '#bfc9e6' }}>
                        Note: high-quality pitch-shifter will be integrated into the AudioWorklet processor. Current worklet is a skeleton; after integrating algorithm the transpose will change pitch while keeping tempo.
                      </div>
                    </div>
                  </div>
                  <div style={{ color: '#dfe6f4', whiteSpace: 'pre-wrap' }}>{logs.join('\n')}</div>
                </div>
              )}
            </div>
          </>
        )}
      </main>

      {renameModalOpen && (
        <div style={{ position: 'fixed', left: 0, top: 0, right: 0, bottom: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.5)', zIndex: 9999 }}>
          <div style={{ background: '#17181d', color: '#f5f7fb', padding: 16, borderRadius: 18, width: 340, boxShadow: '0 22px 50px rgba(0,0,0,0.36)', border: '1px solid rgba(255,255,255,0.05)' }}>
            <h3 style={{ marginTop: 0 }}>Rename playlist</h3>
            <input value={renameValue} onChange={(e)=>setRenameValue(e.target.value)} style={{ width: '100%', padding: 10, marginBottom: 12, borderRadius: 10, border: '1px solid rgba(255,255,255,0.08)', background: 'rgba(255,255,255,0.04)', color: '#f5f7fb' }} />
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
              <button onClick={cancelRename} style={{ borderRadius: 10, border: '1px solid rgba(255,255,255,0.1)', background: 'rgba(255,255,255,0.04)', color: '#f5f7fb', padding: '8px 12px' }}>Cancel</button>
              <button onClick={confirmRename} style={{ borderRadius: 10, border: 'none', background: 'linear-gradient(135deg, #ff9c4b, #ff6b6b)', color: '#fff', padding: '8px 12px' }}>OK</button>
            </div>
          </div>
        </div>
      )}

      {lyricsVisible && (
        <div style={{ position: 'fixed', left: 0, top: 0, right: 0, bottom: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.63)', zIndex: 10000 }}>
          <div style={{ background: '#17181d', color: '#f5f7fb', padding: 16, borderRadius: 20, width: '70%', maxWidth: 800, maxHeight: '80%', overflow: 'auto', boxShadow: '0 22px 50px rgba(0,0,0,0.32)', border: '1px solid rgba(255,255,255,0.08)' }}>
            <h3 style={{ marginTop: 0 }}>Lyrics</h3>
            <div style={{ marginBottom: 8 }}>
              <label style={{ marginRight: 8, color: '#dfe6f4' }}>Display mode:</label>
              <select value={lyricsMode} onChange={(e)=>setLyricsMode(e.target.value as any)} style={{ background: 'rgba(255,255,255,0.04)', color: '#f5f7fb', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 10, padding: '8px 10px' }}>
                <option value="static" style={{ background: '#17181d' }}>Static (no timestamps)</option>
                <option value="synchronized" style={{ background: '#17181d' }}>Synchronized (show timestamps if available)</option>
              </select>
            </div>
            <div ref={lyricsContainerRef} style={{ maxHeight: 400, overflow: 'auto', background: 'rgba(255,255,255,0.02)', padding: 12, borderRadius: 14, border: '1px solid rgba(255,255,255,0.04)' }}>
              {lyricsMode === 'static' ? (
                <pre style={{ whiteSpace: 'pre-wrap', margin: 0, fontSize: '0.95rem', lineHeight: 1.7, color: '#edf3ff' }}>{(lyricsRaw) ? lyricsRaw : (lyricsTimed ? lyricsTimed.map(l=>l.text).join('\n') : 'No lyrics found')}</pre>
              ) : (
                <div style={{ maxHeight: 360 }}>
                  {lyricsTimed && lyricsTimed.length ? (
                    lyricsTimed.map((l, i) => (
                    <div id={`lyr-line-${i}`} key={i} role="button" tabIndex={0} aria-label={`Seek to ${formatTime(l.time)}`} onClick={()=>seekAndPlay(l.time)} onKeyDown={(e)=>{ if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); seekAndPlay(l.time); } }} className="lyric-line" style={{ padding: '9px 10px', background: (i === lyricsIndex) ? 'linear-gradient(135deg, rgba(255,156,75,0.24), rgba(255,107,107,0.14))' : 'transparent', borderRadius: 10, transition: 'background 0.08s', fontWeight: (i === lyricsIndex) ? 800 : 400, color: (i===lyricsIndex)?'#fff':'#dfe6f4', cursor: 'pointer', marginBottom: 2 }}>
                        <span style={{ color: '#cdd9f8', marginRight: 10, fontFamily: 'monospace', fontSize: '0.78rem' }}>{`${Math.floor(l.time/60)}:${String(Math.floor(l.time%60)).padStart(2,'0')}`}</span>
                        <span style={{ fontSize: (i===lyricsIndex)? '1.05em' : '1em' }}>{l.text}</span>
                      </div>
                    ))
                  ) : (
                    <pre style={{ whiteSpace: 'pre-wrap', margin: 0, fontSize: '0.95rem', lineHeight: 1.7, color: '#edf3ff' }}>{lyricsRaw || 'No synchronized lyrics found'}</pre>
                  )}
                </div>
              )}
            </div>
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 8 }}>
              <button onClick={()=>{ setLyricsVisible(false); setLyricsRaw(null); setLyricsTimed(null); }} style={{ borderRadius: 10, border: '1px solid rgba(255,255,255,0.1)', background: 'rgba(255,255,255,0.04)', color: '#f5f7fb', padding: '8px 12px' }}>Close</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function getBackingCandidates(path: string) {
  const pth = (path || '').replace(/\\/g, '/');
  if (!pth) return [] as string[];
  const dir = pth.replace(/\/[^/]*$/, '');
  const base = (pth.split('/').pop() || '').replace(/\.[^/.]+$/, '');
  return [
    `${dir}/${base}_backingtrack.mp3`,
    `${dir}/${base}_backingtrack.wav`
  ];
}

function togglePlayback() {
  const a = audioRef.current;
    const idx = current ?? selected;
    if (!a) {
      if (idx != null && tracks[idx]) playIndex(idx);
      return;
    }
    if (a.paused) {
      const p = a.play();
      if (p && typeof (p as any).then === 'function') {
        (p as any).then(() => setIsPlaying(true)).catch(() => setIsPlaying(false));
      } else {
        setIsPlaying(true);
      }
      return;
    }
    a.pause();
    setIsPlaying(false);
  }

  function toggleBackingTrack() {
    const idx = current ?? selected;
    if (idx == null) return;
    const track = tracks[idx];
    if (!track || !track.path) return;
    const available = !!track.id && !!backingAvailableMap[track.id];
    if (!available) return;

    const nextUseBacking = !Boolean(track.backingActive);
    setTracks(prev => prev.map((item, i) => i === idx ? { ...item, backingActive: nextUseBacking } : item));
  }

:root{
 /* Design tokens */
 --bg: #fffaf0;
 --surface: #fff6e8;
 --muted: #6b6b6b;
 --accent: #ffb84d;
 --accent-strong: #ff8c00;
 --card: #fff8f0;
 --glass: rgba(255,255,255,0.06);
 --radius: 12px;
 --radius-sm: 8px;
 --gap: 16px;
 --shadow-1: 0 6px 18px rgba(2,6,23,0.06);
 --shadow-2: 0 12px 36px rgba(2,6,23,0.08);
 --focus: 3px;
 --max-width: 1200px;
}

/* Dark theme override */
@media (prefers-color-scheme: dark){
 :root{
   --bg: #0f1221;
   --surface: #0b0d16;
   --muted: #9aa0b4;
   --accent: #6fe3ff;
   --accent-strong: #28c7ff;
   --card: #0d1117;
   --glass: rgba(255,255,255,0.03);
   --shadow-1: 0 8px 30px rgba(2,6,23,0.5);
   --shadow-2: 0 14px 48px rgba(2,6,23,0.6);
 }
}

*{box-sizing:border-box}
html,body,#root{height:100%}
body{margin:0;font-family:Inter,system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial, sans-serif;background:radial-gradient(circle at top, #2b2931 0%, #17181d 28%, #0c0d10 100%);color:#f5f7fb;-webkit-font-smoothing:antialiased}

/* Layout */
.app{display:flex;height:100vh;gap:var(--gap);padding:20px;overflow:auto}

/* Playlists panel */
.playlists{width:22%;min-width:140px;flex:0 0 22%;display:flex;flex-direction:column;padding:16px 16px 8px;border-radius:var(--radius);background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));box-shadow:var(--shadow-1);max-height:calc(100vh - 40px);position:relative;min-height:0}
.playlists h2{margin:0 0 12px 0;font-size:1rem;color:var(--muted)}
.playlists .actions{display:flex;gap:8px;margin-bottom:12px}

/* Cards & utilities */
.card{background:var(--card);border-radius:var(--radius);box-shadow:var(--shadow-1);padding:12px}
.glass{background:linear-gradient(180deg,rgba(255,255,255,0.03),rgba(255,255,255,0.01));backdrop-filter:blur(6px);border-radius:var(--radius)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:8px 12px;border-radius:10px;border:none;cursor:pointer;font-weight:600}
.btn-primary{background:linear-gradient(180deg,var(--accent),var(--accent-strong));color:#fff;box-shadow:var(--shadow-1)}
.btn-ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted)}

/* Playlist list */

.playlists .track-list{
  list-style:none;
  padding:0;
  margin:0;
  overflow:auto;
  flex:1;
  display:flex;
  flex-direction:column;
  gap:8px;
  min-height:0;
}
.playlists .track-list li{
  padding:12px 14px;
  margin-bottom:6px;
  border-radius:var(--radius-sm);
  cursor:pointer;
  color:var(--muted);
  display:block;
  outline:none;
  font-size:0.88rem;
  line-height:1.4;
  white-space:normal;
  word-break:break-word;
  background:rgba(255,255,255,0.03);
  border:1px solid transparent;
}
.playlists .track-list li:last-child{margin-bottom:0}
.playlists .track-list li:hover{background:rgba(0,0,0,0.03);transform:translateY(-1px);transition:transform .12s ease, background .12s ease}
.playlists .track-list li[aria-selected='true']{background:linear-gradient(90deg, rgba(255,184,77,0.12), rgba(255,140,0,0.06));box-shadow:0 6px 18px rgba(255,140,0,0.06);color:var(--card)}

/* Player area */
.player{flex:1;min-width:0;display:flex;flex-direction:column;gap:18px}
.player .now{display:flex;gap:20px;align-items:center}
.cover{width:240px;min-width:120px;height:240px;border-radius:var(--radius);display:flex;align-items:center;justify-content:center;color:var(--muted);overflow:hidden;box-shadow:var(--shadow-2);background:linear-gradient(180deg,#fff3d6,#ffe6b8)}
.cover img{width:100%;height:100%;object-fit:cover}

/* Controls */
.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.controls button{background:linear-gradient(180deg,var(--accent),var(--accent-strong));color:#fff;border:none;padding:10px 14px;border-radius:10px;cursor:pointer;font-weight:700;box-shadow:var(--shadow-1)}
.controls button.ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted);box-shadow:none}
.controls button:hover{transform:translateY(-3px);transition:transform .14s cubic-bezier(.2,.9,.2,1)}

/* Misc */
audio{width:100%;background:transparent}
.debug{background:rgba(255,255,255,0.02);padding:12px;border-radius:8px;color:var(--muted);font-size:13px}

/* Drop states */
.playlists.drop-active{box-shadow:0 10px 30px rgba(255,80,80,0.12);border:1px dashed rgba(255,80,80,0.6)}
.drop-overlay{position:absolute;left:12px;right:12px;top:50%;transform:translateY(-50%);width:auto;height:120px;display:flex;align-items:center;justify-content:center;pointer-events:none;color:#ff6b6b;border-radius:8px;background:linear-gradient(180deg,rgba(255,80,80,0.06),rgba(255,40,40,0.03));border:2px dashed rgba(255,80,80,0.5);font-weight:700;font-size:14px;z-index:20}
.drop-zone{flex:1;min-height:0;max-height:none;overflow:auto;padding:8px;border-radius:8px}

/* Seek bar */
.seek{display:flex;align-items:center;gap:12px;margin-right:12px;flex:1;min-width:200px}
.seek .time{font-size:0.85rem;color:var(--muted);min-width:48px;text-align:center}
.seek input[type=range]{-webkit-appearance:none;width:100%;height:8px;border-radius:999px;background:linear-gradient(90deg,var(--accent),var(--accent-strong));outline:none}
.seek input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;border-radius:50%;background:#fff;box-shadow:0 2px 6px rgba(0,0,0,0.2)}

/* Icon buttons and audio controls */
.icon-btn{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:12px;cursor:pointer;box-shadow:0 10px 24px rgba(0,0,0,0.16);color:var(--muted)}
.icon-btn:hover{transform:translateY(-1px);filter:brightness(1.06)}
/* Active state for backing button */
.icon-btn.active{background:linear-gradient(180deg,var(--accent),var(--accent-strong));color:#fff;box-shadow:0 10px 30px rgba(255,140,0,0.18);transform:translateY(-2px)}
.icon-btn[aria-pressed="true"]{outline:2px solid rgba(255,140,0,0.18);}

.control-group{display:flex;align-items:center;gap:8px}
.audio-controls input[type=range]{-webkit-appearance:none;height:6px;border-radius:999px;background:linear-gradient(90deg,rgba(255,255,255,0.9),rgba(180,205,255,0.8));box-shadow:inset 0 0 0 1px rgba(255,255,255,0.08)}
.audio-controls input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;border-radius:50%;background:#f5f7fb;border:2px solid rgba(61,123,255,0.75);box-shadow:0 2px 8px rgba(0,0,0,0.35)}

/* Accessibility & reduced motion */
@media (prefers-reduced-motion: reduce){*{transition:none!important;animation:none!important}}
:focus{outline:none}
:focus-visible{box-shadow:0 0 0 var(--focus) rgba(40,135,255,0.18);border-radius:6px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

