@media (max-width:900px){.app{flex-direction:column;padding:12px}.playlists{width:100%;max-height:220px}.cover{width:100%;height:220px}}

/* Unified form control styles */
input[type="text"], input[type="search"], input[type="password"], input[type="number"], textarea, select {
  background: var(--card);
  color: var(--muted);
  border: none;
  padding: 8px 10px;
  border-radius: 8px;
  box-shadow: var(--shadow-1);
  font-family: inherit;
  font-size: 0.95rem;
  outline: none;
}

textarea{min-height:80px;resize:vertical}

select{appearance:none;-webkit-appearance:none;position:relative;padding-right:32px}

/* custom small form variants (used near lists and compact controls) */
.form-compact input, .form-compact select, .form-compact textarea{padding:6px 8px;font-size:0.88rem;border-radius:6px}

/* focus state consistent with general focus-visible */
input[type="text"]:focus, input[type="search"]:focus, textarea:focus, select:focus{box-shadow:0 0 0 var(--focus) rgba(40,135,255,0.12)}

/* Make file inputs visually consistent by styling their trigger buttons where used */
input[type="file"]{display:none}

/* Ensure icon-btns and text controls align nicely */
.control-row{display:flex;align-items:center;gap:8px}

/* Helper for applying same card background to inline controls (eg. selects near headings) */
.inline-control{background:var(--card);padding:6px 8px;border-radius:8px;box-shadow:var(--shadow-1)}

